add(651, [
'''808 סטייט קמו במנצ׳סטר ב־1987, סביב חנות תקליטים קטנה בשם איסטרן בלוק, ובמרכזם גרהם מאסי, מרטין פרייס, ושני נערים צעירים שהצטרפו אליהם, אנדי בארקר ודארן פארטינגטון. השם לקוח ממכונת התופים המפורסמת רולנד TR-808. הם היו מהבריטים הראשונים שלקחו את מוזיקת האסיד האוס והטכנו של שיקגו ודטרויט והפכו אותה למשהו משלהם. Ninety, שיצא בסוף 1989, הוא אלבומם הראשון בחברת תקליטים גדולה, ולמעשה פסקול של קיץ האהבה השני של בריטניה, הקיץ שבו כל המדינה רקדה במסיבות ענק.''',
'''אין כאן כמעט שירה: רק מכונות תופים, סינתיסייזרים, בס אלקטרוני ודגימות, שנבנים לאט לשכבות של צליל. הקטעים ארוכים ומהפנטים, ונועדו גם לרחבת הריקודים וגם להאזנה בבית. Pacific 202, הלהיט הגדול, נבנה סביב צליל של סקסופון רך וקולות של ציפורים וגלים, והוא נשמע כמו חוף טרופי בשעת שקיעה, אחרי לילה ארוך של ריקודים. Cobra Bora מהיר ואפל יותר, עם בס עמוק ומאיים. Magical Dream פותח את האלבום בקול חולמני ובקצב מקפץ, ו־Donkey Doctor ו־Sunrise קופצניים ושמחים.''',
'''Pacific הגיע לעשירייה הראשונה במצעד הבריטי, והוכיח שמוזיקה אלקטרונית בלי מילים יכולה להיות להיט. 808 סטייט השפיעו על כל מוזיקת הריקודים הבריטית של שנות התשעים, ועל להקות כמו אורביטל והכימיקל ברדרס. הם גם עבדו עם ביורק מהסוגרקיובס (אלבום 631), עוד לפני שהתחילה את קריירת הסולו שלה.''',
'''שמעו את Pacific 202 בשעת ערב, עם חלון פתוח. ואחר כך שמעו את Technique של ניו אורדר (אלבום 638), שהוקלט באותו קיץ ובאותה אווירה, בצד הרוק של מנצ׳סטר.''',
], [
('Pacific 202', 'הלהיט, סקסופון רך, ציפורים וגלים, כמו חוף טרופי בשקיעה אחרי לילה של ריקודים.'),
('Cobra Bora', 'קטע מהיר ואפל, עם בס עמוק ומאיים ומכונת תופים שלא נחה לרגע.'),
('Magical Dream', 'הפותח, קול חולמני וקצב מקפץ, כמו כניסה למסיבה גדולה בלילה.'),
])

add(652, [
'''קולדקאט הם צמד תקליטנים מלונדון, מאט בלאק וג׳ונתן מור, שהתחילו בתחנת רדיו פיראטית ובחנות תקליטים. הם היו מהראשונים בבריטניה שהפכו את אמנות הדגימה לאמנות של ממש: לקחו קטעים מתקליטים ישנים, מסרטים ומשידורים, וחיברו אותם יחד לשירים חדשים. כבר ב־1987 הם הוציאו רמיקס מפורסם בשם Paid in Full לשיר של אריק בי וראקים, ששינה את הדרך שבה אנשים חשבו על רמיקסים. What's That Noise?, שיצא ב־1989, הוא אלבום הבכורה שלהם.''',
'''האלבום הוא אוסף צבעוני של סגנונות: האוס, היפ הופ, רגאיי, סול ופופ, וכל שיר עם זמר או זמרת אורחים אחרים. People Hold On הוא שיר סול ואוס אופטימי, עם הזמרת הצעירה ליסה סטנספילד, שהפך אותה לכוכבת ופתח לה קריירה ענקית. Beats & Pieces, הסינגל הראשון שלהם, הוא קולאז׳ מהיר ומבריק של דגימות מכל עבר, שנשמע כמו תקליטן משוגע. Stop This Crazy Thing מחבר רגאיי עם האוס, בשירתו של הזמר הג׳מייקני ג׳וניור ריד. לצד השירים יש באלבום גם קטעים ניסיוניים יותר, קולאז׳ים של צלילים, קולות ודגימות שנשמעים כמו סרט קצר או שידור רדיו משוגע.''',
'''קולדקאט הקימו אחר כך את חברת התקליטים נינג׳ה טיון, שהפכה לבית של מוזיקה אלקטרונית ניסיונית, והמשיכו לשלב מוזיקה עם סרטים ועם אמנות וידאו. הם השפיעו על דור שלם של תקליטנים ומפיקים, שלמדו מהם שאפשר ליצור מוזיקה חדשה לגמרי מחלקים של מוזיקה ישנה.''',
'''שמעו את People Hold On, ושימו לב לקול של ליסה סטנספילד, אז עוד זמרת לא מוכרת. ואחר כך נסו את Paul's Boutique של הביסטי בויז (אלבום 643), עוד חגיגה של אמנות הדגימה מאותה שנה.''',
], [
('People Hold On', 'שיר סול ואוס אופטימי, עם ליסה סטנספילד הצעירה, שפתח לה קריירה ענקית.'),
('Beats & Pieces', 'הסינגל הראשון, קולאז׳ מהיר ומבריק של דגימות, כמו תקליטן משוגע בעבודה.'),
('Stop This Crazy Thing', 'רגאיי שפוגש האוס, בשירתו החמה של הזמר הג׳מייקני ג׳וניור ריד.'),
])

add(653, [
'''בארי אדמסון גדל במוס סייד, שכונה ענייה וקשה במנצ׳סטר, והתפרסם כבסיסט של להקת הפוסט־פאנק מגזין, ואחר כך כחבר בלהקה של ניק קייב, הבד סידס. הוא אהב תמיד מוזיקת סרטים, ובמיוחד את הפסקולים של סרטי הבלש והפשע האמריקאיים של שנות החמישים והשישים. Moss Side Story, אלבום הסולו הראשון שלו, יצא ב־1989, והוא פסקול לסרט שלא קיים: סרט אפל ומדומיין, שמתרחש בשכונת ילדותו, עם פשע, רדיפה, מוות ותקווה קטנה. הוא עבד על האלבום כמעט לבד, ניגן בעצמו בכלים רבים, וכתב אותו כמו תסריט.''',
'''אין כאן שירים רגילים, אלא קטעים קצרים וארוכים שבונים סיפור בלי מילים: תזמורת כלי מיתר, כלי נשיפה של ג׳אז, פסנתר אפל, אורגן, תופים, צלילי רחוב, יריות, צעדים וצפירות משטרה. לפעמים נשמע כאילו המנגינות לקוחות מסרט של היצ׳קוק, ולפעמים מסרט בלשים זול משנות החמישים. יש קטעים של ג׳אז מהיר ועצבני, קטעים איטיים ועצובים של כלי מיתר, ורגעים מפחידים של שקט ומתח. בחלק מהקטעים מופיע קולה הצורח והחריף של הזמרת דיאמנדה גאלאס, כמו דמות שמחפשת עזרה בלילה.''',
'''האלבום פתח לאדמסון קריירה ארוכה של מוזיקה לסרטים אמיתיים: הוא כתב ועיבד מוזיקה לסרטים של במאים כמו דייוויד לינץ׳ ואוליבר סטון, והמשיך להוציא אלבומים בסגנון של "פסקול לסרט דמיוני". הוא נחשב לאחד האמנים המקוריים של הסצנה הבריטית, שחיבר בין פוסט־פאנק, ג׳אז וקולנוע. האלבום זכה לשבחים רבים מצד מבקרים בבריטניה.''',
'''שמעו את האלבום בחושך, ברצף, ודמיינו את הסרט בעיניים עצומות. כל קטע הוא סצנה: מרדף, פגישה סודית, לילה גשום. בסוף תגלו שבניתם לעצמכם עלילה שלמה.''',
], [
('On the Wrong Side of Relaxation', 'קטע ג׳אז עצבני ומהיר, כמו מרדף ברחובות חשוכים של עיר תעשייה.'),
('Under Wraps', 'קטע איטי ומסתורי, עם כלי מיתר ואווירה של פגישה סודית בלילה.'),
('Central Control', 'קטע מתוח ומאיים, עם תופים וצפירות, כמו רגע השיא של סרט פשע.'),
])

add(654, [
'''אירוסמית׳, הלהקה מבוסטון שהופיעה כאן עם Toys in the Attic ו־Rocks (אלבומים 331 ו־359), כמעט התפרקה בתחילת שנות השמונים בגלל סמים ומריבות. אחרי שראן די.אם.סי החזירו אותם לתודעה עם Walk This Way (אלבום 578), חברי הלהקה נגמלו, התפכחו, וחזרו לעבוד ברצינות. Pump, שיצא ב־1989 בהפקת ברוס פיירבירן, הוא האלבום שבו הם חזרו לשיאם, ונשמעו רעננים, מלאי אנרגיה וחדים יותר מאי פעם.''',
'''הצליל מלוטש אבל עדיין מחוספס: גיטרות של ג׳ו פרי וברד וויטפורד, כלי נשיפה, מפוחית, וקולו הצרוד והגמיש של סטיבן טיילר, שעובר מצעקה לשירה רכה. בין השירים יש קטעים קצרים ומוזרים של כלים מכל העולם, שמחברים את האלבום לרצף אחד. Love in an Elevator הוא שיר רוק מצחיק וקופצני, עם פזמון ענק. Janie's Got a Gun הוא שיר אפל ורציני על נערה שסבלה בבית ונוקמת, והוא הראה צד בוגר ורגיש של הלהקה. The Other Side קצבי ושמח, עם כלי נשיפה, ו־What It Takes היא בלדה כואבת על פרידה.''',
'''Pump מכר מיליוני עותקים, וזכה בגראמי על Janie's Got a Gun. הוא הוכיח שלהקה שכמעט נשמדה מהתמכרויות יכולה לחזור, ולהיות טובה אפילו יותר. אירוסמית׳ המשיכו להצליח בשנות התשעים, והפכו לאחת הלהקות הוותיקות והאהובות באמריקה. סטיבן טיילר וג׳ו פרי, שנקראו פעם "התאומים הרעילים", הפכו לדוגמה של חברים שהצליחו להתגבר יחד.''',
'''שמעו את Love in an Elevator בקול רם, ואחר כך את Janie's Got a Gun בשקט, עם תשומת לב למילים. ואחר כך חזרו ל־Toys in the Attic (אלבום 331), כדי לשמוע את הלהקה הצעירה, חמש־עשרה שנה קודם.''',
], [
('Going Down / Love in an Elevator', 'שיר רוק מצחיק וקופצני, עם גיטרות חדות ופזמון ענק לשירה בקהל.'),
('Water Song / Janie’s Got a Gun', 'שיר אפל ורציני על נערה שסבלה בבית, שזכה בגראמי והראה צד בוגר.'),
('What It Takes', 'בלדה כואבת על פרידה, עם קולו הצרוד והרגשי של סטיבן טיילר.'),
])

add(655, [
'''הפיקסיז כבר הופיעו כאן עם Surfer Rosa (אלבום 623), אלבום גולמי ורועש. Doolittle, שיצא ב־1989, הוא הצעד הבא: מלוטש, מגוון וקליט יותר, בהפקת גיל נורטון, שנתן לשירים צליל נקי וברור. בלאק פרנסיס עדיין כותב על דברים מוזרים: סרטים סוריאליסטיים, תנ״ך, מוות, הים, וזיהום של כדור הארץ, אבל הפעם יש גם מנגינות פופ שכל אחד יכול לזמזם. האלבום הגיע לעשירייה הראשונה במצעד הבריטי, ונמכר יפה גם באמריקה.''',
'''המעבר בין שקט לרעש עדיין שם, והוא אפילו חד יותר: בתים לוחשים עם בס פשוט של קים דיל, ואז פזמונים שמתפוצצים בצעקות ובגיטרות של ג׳ואי סנטיאגו. Debaser, הפותח, מתאר סרט סוריאליסטי ישן של לואיס בוניואל וסלבדור דאלי, ופרנסיס צועק בו שהוא רוצה להיות כמו הדמות. Here Comes Your Man הוא שיר פופ מתוק ושמח, כמעט מהשישים. Monkey Gone to Heaven עוסק בזיהום הים ובאלוהים, עם כלי מיתר. Wave of Mutilation מתאר נהיגה לתוך הים, ו־Tame מתחלף בין לחישה לצרחה. La La Love You הוא שיר אהבה מצחיק, שהמתופף דייוויד לאברינג שר.''',
'''Doolittle נחשב לאלבום הטוב ביותר של הפיקסיז, ולאחד מאבני היסוד של הרוק האלטרנטיבי. להקות כמו נירוונה, רדיוהד וויזר הושפעו ממנו ישירות, והוא מופיע שוב ושוב ברשימות של האלבומים החשובים בכל הזמנים. קורט קוביין אמר שכתב את Smells Like Teen Spirit בניסיון לחקות את הפיקסיז.''',
'''שמעו את Debaser ואחריו את Here Comes Your Man: הצרחה והחיוך, שני הצדדים של הפיקסיז. ואחר כך נסו את Bossanova (אלבום 669), שיצא שנה אחר כך, וחלומי יותר.''',
], [
('Debaser', 'הפותח, שיר צועק ומשמח על סרט סוריאליסטי ישן, עם בס מוביל של קים דיל.'),
('Here Comes Your Man', 'שיר פופ מתוק ושמח, כמעט משנות השישים, שכל אחד יכול לזמזם.'),
('Monkey Gone to Heaven', 'שיר על זיהום הים ועל אלוהים, עם כלי מיתר וצעקות מרגשות.'),
])

add(656, [
'''בוני רייט, בתו של זמר ברודווי מפורסם, התאהבה כבר כנערה בבלוז, ובגיל צעיר הפכה לאחת מנגנות גיטרת הסלייד הטובות באמריקה. במשך כמעט עשרים שנה היא הוציאה אלבומים טובים שזכו להערכה אבל לא נמכרו הרבה, וגם נאבקה בבעיית שתייה. בסוף שנות השמונים היא הפסיקה לשתות, חתמה בחברת תקליטים חדשה ועבדה עם המפיק דון וואז. Nick of Time, שיצא ב־1989, כשהייתה כבר בת ארבעים, הפך אותה בבת אחת לכוכבת.''',
'''הצליל חם ובוגר: גיטרת סלייד מתגלגלת, אורגן, בס עמוק, תופים פשוטים, וקולה של רייט, צרוד, חכם ומלא הומור. השירים מדברים על אהבה בגיל מבוגר, על הזדקנות, על פרידות ועל מציאת הכוח להמשיך. Nick of Time, שיר הנושא שכתבה בעצמה, מספר על אישה שמבינה שהזמן עובר, ועל אהבה שמגיעה "ברגע האחרון". Thing Called Love, שכתב ג׳ון היאט, הוא רוקנרול שמח ומלא ביטחון. Love Letter קצבי ומקפץ, ו־I Ain't Gonna Let You Break My Heart Again הוא בלוז איטי ונוגה, על החלטה לא לחזור לאהבה שפגעה.''',
'''האלבום הגיע למקום הראשון במצעד האמריקאי, וזכה בארבעה פרסי גראמי, כולל אלבום השנה. זה היה אחד הקאמבקים המרגשים של התקופה, והוכיח שאמנית יכולה להגיע לשיא שלה בגיל ארבעים, אחרי עשרים שנה של עבודה קשה. רייט ממשיכה להופיע ולזכות בפרסים עד היום.''',
'''שמעו את Nick of Time בשקט, עם תשומת לב למילים. ואחר כך שמעו את I'm in the Mood, הדואט שלה עם ג׳ון לי הוקר, מ־The Healer (אלבום 637), שהוקלט באותה תקופה.''',
], [
('Nick of Time', 'שיר הנושא שכתבה בעצמה, על אישה שמבינה שהזמן עובר ומוצאת אהבה ברגע האחרון.'),
('Thing Called Love', 'שיר רוקנרול שמח ובטוח של ג׳ון היאט, עם גיטרת סלייד מתגלגלת.'),
('Love Letter', 'שיר קצבי ומקפץ, עם גרוב של בלוז וקול צרוד ומשועשע.'),
])

add(657, [
'''פוגאזי קמו בוושינגטון הבירה ב־1987, ובראשם איאן מקיי, שהיה קודם הזמר של מיינור ת׳רט, להקת הארדקור משפיעה, והקים את חברת התקליטים העצמאית דישורד. לצדו ניגנו גאי פיצ׳וטו, שכתב ושר גם הוא, הבסיסט ג׳ו לאלי והמתופף ברנדן קאנטי. הם היו ידועים בעקרונות שלהם: כרטיס להופעה עלה חמישה דולרים בלבד, כל ההופעות היו פתוחות לכל הגילים, והם סירבו למכור חולצות ומזכרות. Repeater, שיצא ב־1990, הוא אלבומם הראשון באורך מלא.''',
'''המוזיקה עזה ומדויקת: גיטרות חדות שנשמעות כמו מסור, בס עמוק ומקפץ, תופים חזקים, ושני זמרים שצועקים, מדברים ושרים בתורות. אבל זה לא פאנק פשוט: יש בו שקט ורעש, קצבים מוזרים, השפעות של רגאיי ופאנק, ומבנים מפתיעים. Merchandise הוא שיר מחאה נגד צרכנות, עם השורה המפורסמת שאתה לא מה שיש לך. Repeater, שיר הנושא, עוסק באלימות ברחובות של עיר הבירה. Turnover פותח בבס מהפנט שמתפוצץ לאט, ו־Blueprint הוא שיר איטי ויפה יחסית, עם מנגינה שנשארת בראש.''',
'''Repeater נמכר במאות אלפי עותקים בלי חברת תקליטים גדולה, בלי פרסום ובלי קליפים, דבר כמעט בלתי אפשרי באותה תקופה. פוגאזי הפכו לסמל של מוזיקה עצמאית ובלי פשרות, והשפיעו על אינספור להקות, שלמדו מהם שאפשר להצליח בלי למכור את עצמך.''',
'''שמעו את Merchandise, והקשיבו למילים: הן נכתבו לפני יותר משלושים שנה, ועדיין רלוונטיות מאוד. ואם אהבתם, נסו את I Against I של בד בריינס (אלבום 581), להקה אחרת מוושינגטון שהשפיעה עליהם. שימו לב איך שני הזמרים מתחלפים, כמו שיחה בין שני אנשים כועסים.''',
], [
('Merchandise', 'שיר מחאה עז נגד צרכנות, עם השורה המפורסמת שאתה לא מה שיש לך.'),
('Turnover', 'הפותח, בס מהפנט שמתפוצץ לאט לגיטרות חדות ולצעקות משחררות.'),
('Blueprint', 'שיר איטי ויפה יחסית, עם מנגינה שנשארת בראש ושירה רגשית.'),
])

add(658, [
'''סול טו סול קמה בלונדון באמצע שנות השמונים כ"סאונד סיסטם", קבוצה של תקליטנים ורמקולים ענקיים שהרימה מסיבות במחסנים ובמועדונים, בדרך של התרבות הג׳מייקנית. בראשה עמד ג׳אזי בי, בנם של מהגרים מאנטיגואה, ולצדו המפיק נלי הופר. הם הקימו גם חנות בגדים, עם סמל של דמות רוקדת עם צמות ראסטה, והפכו לתנועה תרבותית של צעירים שחורים בבריטניה. Club Classics Vol. One, שיצא ב־1989, הוא אלבום הבכורה, ובאמריקה יצא בשם Keep On Movin'.''',
'''הסוד הוא הקצב: מקצב איטי ומתנדנד של היפ הופ, עם בס עמוק כמו של רגאיי, כלי מיתר של סול ישן, וקולות חמים. זה צליל של מסיבה בשעה מאוחרת, כשכולם מתנדנדים לאט. Back to Life, עם הזמרת קרון וילר, מופיע באלבום בגרסה כמעט בלי כלים, רק קולות, והגרסה עם הקצב הפכה לאחד השירים המזוהים ביותר עם סוף שנות השמונים. Keep On Movin' הוא שיר אופטימי על התמדה והמשך דרך, עם כלי מיתר מרגשים. Fairplay ו־Holdin' On מלאים בגרוב, ו־African Dance מחבר מקצבים אפריקאיים עם מועדון לונדוני.''',
'''האלבום זכה להצלחה עצומה בבריטניה ובאמריקה, ושני שירים ממנו הגיעו לעשירייה הראשונה במצעד הבריטי, ואחד מהם למקום הראשון. הקצב של סול טו סול השפיע על כל מוזיקת הסול, ה־R&B וההיפ הופ של שנות התשעים, ועל הסצנה של בריסטול, שממנה צמחו מאסיב אטאק. נלי הופר הפך אחר כך למפיק מבוקש, ועבד עם ביורק ועם מדונה.''',
'''שמעו את Back to Life בגרסת הקולות שבאלבום, ואחר כך חפשו את הגרסה הקצבית שלו, שכבשה את המצעדים. ואחר כך נסו את Raw Like Sushi של ננה צ׳רי (אלבום 647), שבו נשמעים אותה לונדון ואותה שנה.''',
], [
('Back to Life (a cappella)', 'גרסת קולות כמעט בלי כלים לאחד השירים המזוהים ביותר עם התקופה.'),
("Keep On Movin'", 'שיר אופטימי על התמדה, עם כלי מיתר מרגשים וקצב מתנדנד.'),
('Fairplay', 'שיר מלא גרוב, עם בס עמוק וקולות חמים של מסיבה מאוחרת.'),
])

add(659, [
'''דה לה סול הם שלושה חברים מאמיטיוויל שבלונג איילנד, ליד ניו יורק: פוזדנוס, טרוגוי ומאסיאו. בזמן שרוב הראפרים של סוף שנות השמונים הציגו את עצמם כקשוחים ומאיימים, הם הופיעו עם פרחים, בגדים צבעוניים וחוש הומור מוזר, ואמרו שהם מביאים את "עידן החיננית". 3 Feet High and Rising, אלבום הבכורה שלהם, יצא ב־1989, והפיק אותו פרינס פול, מפיק צעיר ומשוגע, שאהב לחבר צלילים מכל מקום אפשרי.''',
'''האלבום בנוי כמו תוכנית רדיו או שעשועון טלוויזיה: בין השירים יש קטעים קצרים ומצחיקים של שאלות, בדיחות ודמויות. השירים עצמם בנויים מעשרות דגימות מכל סוגי המוזיקה: פאנק, סול, ג׳אז, רוק, תוכניות ילדים, ואפילו שירי פופ רכים של שנות השבעים. Me Myself and I, הלהיט, בנוי על דגימה של פאנקדליק (אלבומים 230 ו־409), והוא שיר על הרצון להיות פשוט עצמך, בלי להתאים לאף תבנית. Eye Know הוא שיר אהבה מתוק, עם שריקה ודגימה של סטילי דן. The Magic Number משתמש בשיר חינוכי לילדים על המספר שלוש. Say No Go הוא שיר נגד סמים, על בסיס של שיר פופ של הול ואוטס.''',
'''האלבום שינה את ההיפ הופ, והראה שאפשר להיות מצחיקים, רכים ומוזרים, ועדיין לעשות ראפ מצוין. הוא היה גם אחד הראשונים שנתבעו בגלל שימוש בדגימה בלי רשות, וכתוצאה מבעיות זכויות הוא לא היה זמין בשירותי הסטרימינג במשך שנים רבות, עד 2023. טרוגוי מת באותה שנה, רגע לפני שהאלבום חזר.''',
'''שמעו את האלבום ברצף, כולל הקטעים הקצרים שבין השירים: הם חלק מהבדיחה. ואחר כך נסו את All Hail the Queen של קווין לטיפה (אלבום 640), חברתם לקבוצת "נייטיב טאנגס".''',
], [
('Me Myself and I', 'הלהיט, על הרצון להיות פשוט עצמך, בנוי על דגימה פאנקית של פאנקדליק.'),
('Eye Know', 'שיר אהבה מתוק ומחויך, עם שריקה ודגימה של סטילי דן.'),
('The Magic Number', 'שיר שמח שבנוי על שיר חינוכי ישן לילדים על המספר שלוש.'),
])

add(660, [
'''ג׳נט ג׳קסון, האחות הצעירה של מייקל (אלבומים 449, 507 ו־606), הצליחה מאוד ב־1986 עם Control, שבו השתחררה מהשליטה של משפחתה. אחרי ההצלחה, חברת התקליטים רצתה אלבום המשך דומה, אבל ג׳נט והמפיקים שלה ממיניאפוליס, ג׳ימי ג׳ם וטרי לואיס, החליטו לעשות משהו אחר: אלבום שמדבר על החברה ועל העולם. Rhythm Nation 1814, שיצא ב־1989, עוסק בגזענות, בעוני, בסמים, באלימות ובחינוך, ומזמין את המאזינים להצטרף ל"אומה" של אנשים שמאמינים בשינוי.''',
'''הצליל קשה וחד: תופים אלקטרוניים חזקים, בס פאנקי, דגימות, רעשים של מכונות ושל עיר, ומקהלות של קולות של ג׳נט עצמה. Rhythm Nation, שיר הנושא, בנוי על דגימה משיר של סליי אנד דה פמילי סטון, והקליפ שלו, בשחור לבן, עם ריקוד צבאי מדויק של עשרות רקדנים במדים, הפך לאחד הקליפים המפורסמים של התקופה. Miss You Much הוא שיר ריקוד קופצני ושמח. Black Cat, שג׳נט כתבה לבד, הוא שיר רוק כבד עם סולו גיטרה. Escapade קליל וקיצי, ו־Love Will Never Do (Without You) הוא שיר אהבה רך שהופך לשמח.''',
'''Rhythm Nation 1814 היה האלבום הראשון בהיסטוריה ששבעה סינגלים ממנו הגיעו לחמשת המקומות הראשונים במצעד האמריקאי. המספר 1814 בשם האלבום מתייחס לשנה שבה נכתב ההמנון האמריקאי. ג׳נט הפכה לאחת הכוכבות הגדולות של העשור הבא, ויצאה מהצל של אחיה.''',
'''שמעו את Rhythm Nation בקול רם, ואחריו את Miss You Much: הצד הרציני והצד הרוקד של האלבום. ואחר כך השוו ל־Bad של מייקל (אלבום 606), שיצא שנתיים קודם.''',
], [
('Rhythm Nation', 'שיר הנושא, קריאה לאחדות על קצב חד, עם אחד הקליפים המפורסמים בתקופה.'),
('Miss You Much', 'שיר ריקוד קופצני ושמח על געגועים, עם בס פאנקי וקולות בשכבות.'),
('Black Cat', 'שיר רוק כבד שג׳נט כתבה לבד, עם סולו גיטרה ושירה כועסת.'),
])

add(661, [
'''הג׳אנגל ברדרס הם שלושה חברים מניו יורק, מייק ג׳י, אפריקה בייבי באם וסמי בי, שהקימו יחד עם דה לה סול ועם א טרייב קולד קווסט את קבוצת "נייטיב טאנגס", "השפות הילידיות". הם היו מהראשונים שהביאו להיפ הופ גאווה באפריקה, ג׳אז, הומור ומסרים חיוביים, והקדימו בכך את חבריהם. כבר באלבום הראשון שלהם הם חיברו ראפ עם מוזיקת האוס, בשיר I'll House You, והמציאו בכך סגנון שלם. Done by the Forces of Nature, אלבומם השני, יצא ב־1989.''',
'''הצליל חם, רגוע ומלא גרוב: דגימות של ג׳אז, סול, פאנק ומוזיקה אפריקאית, תופים קלים, וראפ שקט, משוחח ומשועשע. השירים מדברים על היסטוריה שחורה, על אהבה, על טבע, על רוחניות ועל מסיבות, ונשמעים כמו שיחה בין חברים בערב קיץ. Doin' Our Own Dang הוא שיר שבו משתתפים חברים רבים מ"נייטיב טאנגס", כמו מסיבה גדולה של חברים. Beyond This World פותח את האלבום באווירה מסתורית. Sunshine הוא שיר רך ושמשי, ו־Black Woman הוא שיר אהבה מכבד לנשים שחורות. U Make Me Sweat קצבי ושמח.''',
'''האלבום לא הצליח מסחרית כמו האלבומים של חבריהם, אבל מבקרים ומוזיקאים רואים בו את אחד האלבומים החשובים של ההיפ הופ החיובי והאפרוצנטרי. הג׳אנגל ברדרס השפיעו על הראפרים "האלטרנטיביים" של שנות התשעים, שחיפשו דרך אחרת מראפ הגנגסטה.''',
'''שמעו את Doin' Our Own Dang, ונסו לזהות את הקולות של החברים מהלהקות האחרות. ואחר כך עברו ל־3 Feet High and Rising של דה לה סול (אלבום 659), שיצא באותה שנה ומאותו בית.''',
], [
("Doin' Our Own Dang", 'שיר שבו משתתפים חברים רבים מ"נייטיב טאנגס", כמו מסיבה גדולה של חברים.'),
('Sunshine', 'שיר רך ושמשי, עם גרוב של ג׳אז וראפ רגוע ומחויך.'),
('Black Woman', 'שיר אהבה מכבד ורך לנשים שחורות, עם דגימה של סול ישן.'),
])

add(662, [
'''אן.דבליו.איי באו מקומפטון, עיר עניה ליד לוס אנג׳לס, שבסוף שנות השמונים סבלה מאלימות של כנופיות, מסמים ומיחס קשה של המשטרה לתושבים השחורים. בקבוצה היו חמישה: איזי־אי, שמימן את התקליטים, איס קיוב, שכתב את רוב המילים, ד״ר דרה, שהפיק את המוזיקה, אם סי רן ודי ג׳יי ילה. Straight Outta Compton, שיצא ב־1988, היה אחד האלבומים הראשונים של מה שנקרא "גנגסטה ראפ": ראפ שמתאר את החיים ברחוב כמו שהם, בלי לייפות, בשפה בוטה מאוד.''',
'''הצליל קשה וחד: מכונת תופים חזקה, דגימות של פאנק וסול, סקרץ׳ ובס עמוק. החרוזים כועסים, מתגרים ולפעמים מצחיקים, ומתארים עולם של אלימות, סמים, כסף ומשטרה. שיר הנושא פותח בהצהרה עוצמתית על המקום שממנו הם באים. שיר מחאה בוטה נגד אלימות שוטרים, שהשם שלו לא מתאים לכתיבה כאן, גרם ל־FBI לשלוח מכתב אזהרה לחברת התקליטים, ושנים אחר כך הפך להמנון של מחאות נגד אלימות משטרתית. Express Yourself, דווקא, הוא שיר קליל ושמח, בלי קללות, על החופש להגיד מה שאתה חושב. Gangsta Gangsta מתאר את חיי הרחוב בגלוי ובצורה מטרידה.''',
'''למרות שהרדיו כמעט לא השמיע אותו, האלבום מכר מיליוני עותקים, ושינה את ההיפ הופ, שהמרכז שלו עבר מניו יורק גם לחוף המערבי. ד״ר דרה ואיס קיוב הפכו בהמשך לכוכבים ענקיים ולאנשי עסקים מצליחים, ואיזי־אי מת ב־1995, בגיל צעיר. ב־2015 יצא סרט קולנוע מצליח על סיפור הקבוצה.''',
'''זה אלבום קשה ובוטה מאוד, עם מילים אלימות וגסות, ולא לכל אחד. אם אתם רוצים להתחיל ממנו, התחילו ב־Express Yourself, שהוא השיר הקליל והנגיש ביותר בו.''',
], [
('Straight Outta Compton', 'שיר הנושא, הצהרה עוצמתית ובוטה על המקום שממנו הם באים, עם קצב חד.'),
('Express Yourself', 'שיר קליל ושמח, בלי קללות, על החופש להגיד מה שאתה חושב.'),
('Gangsta Gangsta', 'תיאור גלוי ומטריד של חיי הרחוב בקומפטון, על בסיס של פאנק כבד.'),
])

add(663, [
'''קוקטו טווינס באו מגריינג׳מאות׳, עיירת תעשייה בסקוטלנד, וכבר הכרנו אותם כאן עם Treasure (אלבום 534). הם היו שלושה: הזמרת אליזבת פרייזר, הגיטריסט רובין גאת׳רי והבסיסט סיימון ריימונד. פרייזר שרה בדרך כלל במילים שאי אפשר להבין, צלילים שהיא המציאה בעצמה, כמו שפה של חלומות. Heaven or Las Vegas, שיצא ב־1990, נכתב אחרי שהיא וגאת׳רי הפכו להורים לבת, והוא החם, הבהיר והנגיש ביותר שלהם.''',
'''הצליל עשוי מגיטרות מהדהדות שנשמעות כמו אור, בס רך ומתגלגל, מכונת תופים פשוטה, וקולה של פרייזר, שעולה ויורד, מתנפץ ומתרכך, כמו ציפור. כאן, בפעם הראשונה, אפשר לשמוע מילים באנגלית פה ושם, ותחושת האושר של הורות חדשה ממלאת את השירים. Cherry-Coloured Funk, הפותח, הוא שיר חלומי וחם, כמו שמש של בוקר. Heaven or Las Vegas, שיר הנושא, נשמע כמו להיט פופ מבריק מעולם אחר. Iceblink Luck קופצני ושמח, ו־Fifty-Fifty Clown רך ומתוק. Frou-Frou Foxes in Midsummer Fires, הסוגר, הוא שיר ארוך ויפה, כמו שקיעה של קיץ.''',
'''האלבום היה המצליח ביותר שלהם, והאחרון בחברת 4AD, שהייתה ביתם במשך עשור. אחריו הלהקה התפרקה לאט, בין השאר בגלל משברים אישיים. Heaven or Las Vegas נחשב היום לאחד מאבני היסוד של מוזיקת הדרים פופ, ולהקות רבות מנסות עד היום לשחזר את הצליל המיוחד שלו.''',
'''שמעו את Heaven or Las Vegas עם אוזניות, ואל תנסו להבין את המילים: תנו לקול להיות עוד כלי. ואחר כך השוו ל־Treasure (אלבום 534), שבו הלהקה נשמעת אפלה ומסתורית יותר.''',
], [
('Cherry-Coloured Funk', 'הפותח, שיר חלומי וחם כמו שמש של בוקר, עם גיטרות מהדהדות ורכות.'),
('Heaven or Las Vegas', 'שיר הנושא, להיט פופ מבריק מעולם אחר, עם קול שעולה ויורד כמו ציפור.'),
('Iceblink Luck', 'שיר קופצני ושמח, עם גיטרה מנצנצת ושמחה של הורות חדשה.'),
])

add(664, [
'''השיימן קמו באברדין שבסקוטלנד, בהתחלה כלהקת רוק פסיכדלי. בסוף שנות השמונים, כשהם עברו ללונדון, הם גילו את סצנת האסיד האוס ומסיבות הרייב, והפכו את עצמם ללהקת ריקודים אלקטרונית. בראשם עמדו קולין אנגוס וויל סינוט, ששילבו בהופעות שלהם במות של להקה חיה עם תקליטנים, תאורה ומסיבה גדולה. En-Tact, שיצא ב־1990, הוא האלבום שבו המעבר הזה הושלם.''',
'''המוזיקה מחברת רוק, פסיכדליה, טכנו, האוס והיפ הופ: מכונות תופים מהירות, סינתיסייזרים, דגימות, גיטרות, ראפ בהשפעה בריטית, ומילים על תודעה, על חופש, על טבע ועל חלומות. Move Any Mountain, הלהיט, הוא שיר ריקוד אופטימי ומרומם, שקורא להאמין שאפשר להזיז הרים. Hyperreal Orbit ו־Hyperreal Selector, שתי גרסאות לאותו שיר, חלומיות ומהפנטות. Make It Mine קופצני וממכר, עם דגימה של קולות. Possible Worlds ו־Omega Amigo נשמעים כמו מסע בתוך מסיבה ענקית, באמצע הלילה. השילוב בין להקת רוק חיה לבין מכונות ותקליטנים נשמע אז חדש ומפתיע, ונתן לשירים אנרגיה של הופעה אמיתית.''',
'''ב־1991, זמן קצר אחרי יציאת האלבום, טבע ויל סינוט למוות בזמן צילומי קליפ באיים הקנריים, ואנגוס החליט להמשיך. בשנים שאחר כך השיימן זכו להצלחה גדולה עוד יותר, והפכו לאחת הלהקות שהביאו את תרבות הרייב לתוך מצעדי הפזמונים הבריטיים. השיר Ebeneezer Goode, שבא אחריהם, הגיע למקום הראשון בבריטניה ועורר ויכוח ציבורי סוער.''',
'''שמעו את Move Any Mountain בקול רם, ודמיינו אולם ענק מלא אנשים שרוקדים עד הבוקר. ואחר כך נסו את Ninety של 808 סטייט (אלבום 651), עוד פסקול של אותו קיץ.''',
], [
('Move Any Mountain', 'הלהיט, שיר ריקוד אופטימי ומרומם שקורא להאמין שאפשר להזיז הרים.'),
('Hyperreal Orbit', 'שיר חלומי ומהפנט על מציאות שנראית אמיתית מדי, עם קול נשי מרחף.'),
('Make It Mine', 'שיר קופצני וממכר, עם דגימות קולות וקצב של מסיבת רייב.'),
])

add(665, [
'''די־לייט קמו בניו יורק, שלושה חברים ממקומות שונים לגמרי: הזמרת ליידי מיס קיר מאוהיו, התקליטן סופר די ג׳יי דמיטרי, שנולד בברית המועצות, והתקליטן טואה טיי מיפן. הם הכירו בסצנת המועדונים של מנהטן, ואהבו פאנק של שנות השבעים, אופנה צבעונית של שנות השישים, האוס ודיסקו. World Clique, אלבום הבכורה שלהם, יצא ב־1990, והפך אותם בבת אחת לסמל של מסיבה צבעונית, אופטימית ופתוחה לכולם.''',
'''הצליל עליז וקופצני: קצב האוס, בס פאנקי, דגימות מכל מקום, כלי נשיפה, ושירה מתוקה, משועשעת ובטוחה של קיר. Groove Is in the Heart, הלהיט הענק, הוא שיר ריקוד מושלם, עם הבס המפורסם של בוטסי קולינס, אגדת הפאנק שניגן עם ג׳יימס בראון ופרלמנט, וקטע ראפ קצר של קיו־טיפ מא טרייב קולד קווסט (אלבום 681). Power of Love הוא שיר אופטימי על אהבה ככוח שמשנה את העולם. Good Beat קצבי ומקפץ, ו־What Is Love? שואל את השאלה הגדולה בקצב של מועדון. גם נגני כלי נשיפה מהלהקה של ג׳יימס בראון משתתפים באלבום, ומוסיפים לו חום ושמחה.''',
'''Groove Is in the Heart הגיע לעשירייה הראשונה בבריטניה ובאמריקה, והפך לאחד השירים האהובים של שנות התשעים, שמנוגן עד היום בכל מסיבה. די־לייט נשארו מזוהים עם האופטימיות והצבעוניות של תחילת העשור, ולא הצליחו לחזור על ההצלחה, אבל השפיעו מאוד על האופנה ועל הפופ שבאו אחריהם.''',
'''שמעו את Groove Is in the Heart, ונסו לא לזוז. ואחר כך שמעו את Mothership Connection של פרלמנט (אלבום 360), שבו בוטסי קולינס ניגן חמש־עשרה שנה קודם.''',
], [
('Groove Is in the Heart', 'הלהיט הענק, שיר ריקוד מושלם עם הבס של בוטסי קולינס וראפ של קיו־טיפ.'),
('Power of Love', 'שיר אופטימי וקופצני על אהבה ככוח שיכול לשנות את העולם.'),
('Good Beat', 'שיר קצבי ומקפץ, עם קצב האוס, כלי נשיפה ושירה משועשעת.'),
])

add(666, [
'''הלה׳ז באו מליברפול, ובמרכזם עמד לי מייברס, כותב שירים מוכשר ואובססיבי, שרצה שהמוזיקה שלו תישמע בדיוק כמו בראש שלו. הלהקה הקליטה את אלבום הבכורה שלה שוב ושוב, במשך שנים, עם מפיקים רבים, ומייברס לא היה מרוצה מאף אחת מהגרסאות. בסוף חברת התקליטים איבדה סבלנות, והמפיק סטיב לילייווייט הרכיב אלבום מתוך ההקלטות. האלבום יצא ב־1990, ומייברס עצמו התכחש אליו ואמר שהוא שונא אותו.''',
'''למרות זאת, זה אלבום נפלא: שירי גיטרה קצרים, פשוטים ומלאי מנגינה, ברוח הביטלס ולהקות ליברפול של שנות השישים, עם גיטרות אקוסטיות וחשמליות, בס מקפץ, ושירה רכה ונלהבת. There She Goes, הלהיט, הוא שיר פופ מושלם של שתי דקות וחצי, עם גיטרה מצלצלת שאי אפשר לשכוח, ושהשתמשו בו בסרטים ובפרסומות רבות. Timeless Melody הוא שיר על החיפוש אחרי המנגינה המושלמת. Feelin' ו־Son of a Gun קופצניים ושמחים, ו־Looking Glass, הסוגר, הוא שיר ארוך שנבנה לאט לשיא סוער.''',
'''הלה׳ז לא הוציאו אלבום נוסף אף פעם, ומייברס נעלם כמעט לגמרי מהעין הציבורית. אבל האלבום היחיד שלהם השפיע מאוד על להקות הבריטפופ של שנות התשעים, כמו אואזיס, שראו בו דוגמה לשירי גיטרה פשוטים ומושלמים. הבסיסט ג׳ון פאוור הקים אחר כך להקה משלו, קאסט, שהצליחה בבריטניה. There She Goes הפך לאחד השירים הבריטיים האהובים של העשור, ולהקות רבות ביצעו אותו בגרסאות משלהן.''',
'''שמעו את There She Goes, ושימו לב כמה הוא קצר ומושלם. ואחר כך שמעו את האלבום כולו ברצף: הוא קצר, ולא נגמר אף פעם מהר מספיק.''',
], [
('There She Goes', 'שיר פופ מושלם של שתי דקות וחצי, עם גיטרה מצלצלת שאי אפשר לשכוח.'),
('Timeless Melody', 'שיר על החיפוש אחרי המנגינה המושלמת, שהוא בעצמו מנגינה כזו.'),
('Looking Glass', 'הסוגר, שיר ארוך שנבנה לאט לשיא סוער ומשחרר של גיטרות.'),
])

add(667, [
'''הבלאק קרואוז באו מאטלנטה שבג׳ורג׳יה, ובמרכזם שני אחים: הזמר כריס רובינסון והגיטריסט ריץ׳ רובינסון, שהתווכחו ונלחמו כל הזמן, אבל כתבו יחד שירים מצוינים. בזמן שהרוק של סוף שנות השמונים היה מלא בשיער מנופח ובצליל מלוטש, הם ניגנו רוקנרול ישן ומחוספס, בהשראת הרולינג סטונס, הפייסס, וסול דרומי. Shake Your Money Maker, אלבום הבכורה, יצא ב־1990, ושמו לקוח משיר בלוז ישן של אלמור ג׳יימס.''',
'''הצליל חם, מלוכלך ומלא נשמה: גיטרות מחוספסות, פסנתר ואורגן של בר, תופים פשוטים, וקולו של כריס רובינסון, צרוד, גבוה ומלא סול. Hard to Handle, גרסה לשיר של אוטיס רדינג (אלבום 51), הפך ללהיט ולהמנון של הלהקה. She Talks to Angels היא בלדה אקוסטית ועצובה על נערה שאבדה בעולם של סמים. Jealous Again הוא רוקנרול קצבי עם פסנתר, ו־Twice as Hard פותח את האלבום בגיטרת סלייד כבדה. Seeing Things הוא שיר נוגה ויפה, עם אורגן וקולות רקע של גוספל. Sister Luck הוא שיר איטי ונוגה, עם אורגן ושירה מלאה ברגש.''',
'''האלבום מכר מיליוני עותקים, והחזיר את הרוקנרול הישן והמחוספס למצעדים, בדיוק כשהגראנג׳ עמד לכבוש את העולם. הבלאק קרואוז הפכו לאחת הלהקות הבולטות של שנות התשעים, למרות המריבות בין האחים, שפירקו את הלהקה והרכיבו אותה מחדש כמה פעמים. המפיק ג׳ורג׳ דרקוליאס, שעבד בחברה של ריק רובין, נתן לאלבום צליל חם וחי, כאילו הוקלט בשנות השבעים.''',
'''שמעו את Hard to Handle, ואחריו את המקור של אוטיס רדינג. ואחר כך את She Talks to Angels, כדי לשמוע את הצד הרך של הלהקה.''',
], [
('Hard to Handle', 'גרסה רוקית וסוערת לשיר של אוטיס רדינג, שהפכה להמנון של הלהקה.'),
('She Talks to Angels', 'בלדה אקוסטית ועצובה על נערה שאבדה, עם קול צרוד ומרגש.'),
('Jealous Again', 'רוקנרול קצבי ומחוספס עם פסנתר של בר, בסגנון הרולינג סטונס.'),
])

add(668, [
'''דפש מוד כבר הופיעו כאן עם Music for the Masses (אלבום 592), שהפך אותם לכוכבים באמריקה. Violator, שיצא ב־1990, הוא האלבום שבו הם הגיעו לשיא: הצליל אפל, נקי ומדויק, והשירים של מרטין גור בשלים ובטוחים יותר מאי פעם. את האלבום הפיק פלאד, מפיק בריטי שעבד גם עם יו־2 וניק קייב, ויחד עם הקלידן אלן ויילדר הם נתנו לכל צליל מקום משלו, בלי עומס ובלי רעש מיותר.''',
'''הצליל מחבר מוזיקה אלקטרונית עם בלוז, גוספל ורוק: סינתיסייזרים אפלים, מכונות תופים חדות, ולפעמים גם גיטרה. דייב גהאן שר בקול עמוק, חושני ובוטח. Personal Jesus בנוי על ריף גיטרה של בלוז, ומדבר על אדם שמציע את עצמו כמושיע אישי, והוא אחד השירים המוכרים ביותר שלהם. ג׳וני קאש הקליט שנים אחר כך גרסה משלו. Enjoy the Silence התחיל כבלדה איטית, ופלאד וויילדר הפכו אותו לשיר ריקוד מושלם ועצוב, על הרצון בשקט ובפחות מילים. Policy of Truth עוסק בשקרים קטנים, ו־World in My Eyes, הפותח, הוא שיר חושני על עולם של חוויות. Halo ו־Waiting for the Night אפלים ושקטים.''',
'''ב־1990, כשהלהקה הגיעה לחנות תקליטים בלוס אנג׳לס לחתום על עותקים, הגיעו עשרות אלפי מעריצים, וההמון הפך להתפרעות. Violator מכר מיליוני עותקים, ונחשב היום ליצירת המופת של דפש מוד, ולאחד האלבומים האלקטרוניים החשובים בכל הזמנים.''',
'''שמעו את Enjoy the Silence ואחריו את Personal Jesus, שני הלהיטים הגדולים, ותשמעו כמה שונים הם, ועדיין באותו עולם. ואחר כך השוו ל־Music for the Masses (אלבום 592).''',
], [
('Enjoy the Silence', 'שיר ריקוד מושלם ועצוב על הרצון בשקט ובפחות מילים, אחד השיאים שלהם.'),
('Personal Jesus', 'ריף גיטרה של בלוז ושיר על מושיע אישי, שג׳וני קאש הקליט שנים אחר כך.'),
('World in My Eyes', 'הפותח, שיר חושני ואלקטרוני על עולם של חוויות ותחושות.'),
])

add(669, [
'''Bossanova, שיצא ב־1990, הוא האלבום השלישי של הפיקסיז, אחרי Surfer Rosa (אלבום 623) ו־Doolittle (אלבום 655). הוא הוקלט בלוס אנג׳לס, ובלאק פרנסיס, שהתעניין מאוד בחלל, בעב״מים ובמוזיקת גלישה של שנות השישים, הביא את כל אלה לשירים. היחסים בתוך הלהקה כבר היו מתוחים, וקים דיל שרה וכתבה הרבה פחות מבעבר. התוצאה חלומית, רחבה ומוזרה יותר מקודמיו, פחות צועקת ויותר מרחפת. את ההקלטות הוביל שוב המפיק גיל נורטון, שעבד איתם על Doolittle.''',
'''הצליל מלא בגיטרות של גלישה עם הדהוד, בצלילים חלליים, ולפעמים גם בתרמין, הכלי שנשמע כמו סרט מדע בדיוני ישן. Cecilia Ann, הפותח, הוא קטע כלי של מוזיקת גלישה. Velouria, הלהיט, הוא שיר אהבה חלומי לאישה מסתורית, עם תרמין שמרחף מעל. Allison הוא שיר קצר ומהיר לכבוד פסנתרן הג׳אז מוז אליסון. Dig for Fire קליל ומקפץ, ו־The Happening מספר על חייזרים שנוחתים בלאס וגאס. Ana הוא שיר רגוע על גלישה, שהשורות שלו מאייתות את המילה "גולש" באנגלית. Rock Music רועש ומטורף, כמו ההופעות שלהם.''',
'''Bossanova לא זכה להערכה כמו קודמיו, אבל עם השנים רבים גילו בו מחדש את האלבום האוורירי והמסתורי של הפיקסיז. האלבום הגיע למקום השלישי במצעד הבריטי, והלהקה התפרקה זמן קצר אחרי האלבום הבא, עד שחזרה ב־2004. גם הצליל של להקות אינדי רבות בשנות התשעים, שאהבו גלישה, חלל וגיטרות מהדהדות, נשען על האלבום הזה.''',
'''שמעו את Velouria, ושימו לב לתרמין שמרחף מעל הגיטרות. ואחר כך שמעו את The Happening, ודמיינו חלליות מעל המדבר.''',
], [
('Velouria', 'הלהיט, שיר אהבה חלומי לאישה מסתורית, עם תרמין שמרחף מעל הגיטרות.'),
('The Happening', 'שיר מוזר ומשעשע על חייזרים שנוחתים בלאס וגאס, עם גיטרות חלליות.'),
('Dig for Fire', 'שיר קליל ומקפץ, עם גיטרה של גלישה ושירה רגועה.'),
])

add(670, [
'''מגאדת׳ כבר הופיעו כאן עם Peace Sells... but Who's Buying? (אלבום 572). בסוף שנות השמונים דייב מאסטיין החליף כמעט את כל הלהקה: הגיטריסט מרטי פרידמן, וירטואוז שאהב גם מוזיקה יפנית וסולמות אקזוטיים, והמתופף ניק מנזה, הצטרפו אליו ואל הבסיסט דייב אלפסון. Rust in Peace, שיצא ב־1990, הוא התוצאה, ונחשב לאלבום הטוב ביותר של מגאדת׳, ולאחד מאלבומי הת׳ראש מטאל הגדולים בכל הזמנים.''',
'''המוזיקה טכנית, מהירה ומדויקת כמעט כמו מוזיקה קלאסית: ריפים מסובכים, שינויי קצב פתאומיים, וסולואים מבריקים, שבהם מאסטיין ופרידמן מתחלפים ומתחרים זה בזה. המילים עוסקות בפוליטיקה, במלחמה, בנשק גרעיני ובסודות של ממשלות. Holy Wars... The Punishment Due, הפותח, מתחיל בגיטרה מהירה ומסתורית, ועוסק במלחמות דת ובסכסוכים בעולם. Hangar 18 מספר על חייזרים שהממשלה האמריקאית מחביאה בבסיס סודי, וכולו כמעט סולואים של גיטרה. Tornado of Souls הוא שיר פרידה, עם אחד הסולואים המפורסמים של פרידמן. Rust in Peace... Polaris, הסוגר, עוסק בטילים גרעיניים. מאסטיין שר בקול חד וצורמני, לפעמים כמעט כמו מספר סיפורים, ונותן לכל שיר אווירה של מותחן.''',
'''האלבום נכנס לשלושים המקומות הראשונים במצעד האמריקאי, וזכה למועמדות לגראמי. גיטריסטים רבים לומדים אותו עד היום כמו שלומדים יצירה קלאסית, תו אחרי תו. אלבום ההמשך שלהם, Countdown to Extinction, הגיע אף למקום השני במצעד האמריקאי.''',
'''שמעו את Hangar 18, ושימו לב איך שני הגיטריסטים מעבירים את הסולו מאחד לשני. ואחר כך השוו ל־Peace Sells (אלבום 572), כדי לשמוע כמה הלהקה התפתחה בארבע שנים.''',
], [
('Holy Wars... The Punishment Due', 'הפותח, גיטרה מהירה ומסתורית ושיר על מלחמות דת וסכסוכים בעולם.'),
('Hangar 18', 'שיר על חייזרים שמוסתרים בבסיס סודי, וכולו כמעט סולואים מבריקים.'),
('Tornado of Souls', 'שיר פרידה סוער, עם אחד הסולואים המפורסמים של מרטי פרידמן.'),
])

add(671, [
'''דיג׳יטל אנדרגראונד באו מאוקלנד שבקליפורניה, ובמרכזם עמד שוק ג׳י, מוזיקאי, מפיק וראפר שאהב את הפאנק של ג׳ורג׳ קלינטון ופרלמנט (אלבום 360). כמו קלינטון, גם הוא אהב תחפושות ודמויות: הוא המציא לעצמו דמות שנייה בשם האמפטי האמפ, עם אף מזויף ענק ומשקפיים מצחיקים, ובראיונות התעקש שמדובר באדם אחר. Sex Packets, אלבום הבכורה, יצא ב־1990, והוא בנוי כמו סיפור מדע בדיוני מצחיק על גלולה מומצאת.''',
'''הצליל הוא פאנק כבד וחם של שנות השבעים, עם דגימות של פרלמנט ופאנקדליק, בס עבה, קלידים מקפצים, וראפ משועשע ומלא בדיחות. The Humpty Dance, הלהיט הגדול, הוא שיר ריקוד מצחיק שבו האמפטי האמפ מציג את עצמו ומתאר את הריקוד המוזר שלו, והקצב שלו הפך לאחד הקצבים שהכי הרבה דגמו בהיסטוריה של ההיפ הופ. Doowutchyalike הוא שיר מסיבה שקורא לכולם לעשות מה שבא להם. Freaks of the Industry מצחיק ונועז, ו־Packet Man הוא סאטירה על סוחרי הגלולות המומצאות. השירים ארוכים ומתגלגלים, כמו מסיבה שלא נגמרת.''',
'''The Humpty Dance הגיע כמעט לעשירייה הראשונה במצעד האמריקאי, והאלבום מכר מיליון עותקים. בשנים שאחרי הצטרף ללהקה כרקדן וכמלווה צעיר בשם טופאק שאקור, שהתחיל איתם את דרכו והפך לאחד הראפרים הגדולים בכל הזמנים. שוק ג׳י מת ב־2021. הקול המצחיק של האמפטי האמפ, שנשמע כאילו הוא מדבר דרך האף, הפך לאחד הקולות הזכורים של התקופה.''',
'''שמעו את The Humpty Dance, ונסו לזהות את הקצב: סביר שכבר שמעתם אותו בעשרות שירים אחרים. ואחר כך שמעו את Mothership Connection של פרלמנט (אלבום 360), כדי לשמוע מאיפה כל זה בא.''',
], [
('The Humpty Dance', 'הלהיט, שיר ריקוד מצחיק עם דמות מומצאת, וקצב שדגמו בעשרות שירים.'),
('Doowutchyalike', 'שיר מסיבה פאנקי וארוך, שקורא לכולם לעשות בדיוק מה שבא להם.'),
('Freaks of the Industry', 'שיר מצחיק ונועז על בס פאנקי עבה, עם שני ראפרים שמתחלפים.'),
])

add(672, [
'''הפט שופ בויז כבר הופיעו כאן עם Actually (אלבום 607), אלבום של שירי ריקוד גדולים ומבריקים. Behaviour, שיצא ב־1990, שקט, עצוב ובוגר יותר. הם הקליטו אותו במינכן עם המפיק הרולד פלטרמאייר, שהתפרסם במוזיקה לסרטים, ובחרו בסינתיסייזרים אנלוגיים ישנים, שנותנים לצליל חום ורכות. גם ג׳וני מאר מהסמית׳ס מנגן בגיטרה בכמה מהשירים.''',
'''השירים איטיים יותר, והמילים של ניל טננט מדברות על התבגרות, על זיכרונות, על אובדן ועל אהבה שלא נגמרה כמו שציפו. Being Boring, השיר הידוע ביותר באלבום, מתאר את הנעורים, את המסיבות ואת החברים, ואת העצב על חברים שאבדו לאורך השנים, ורבים רואים בו את השיר היפה ביותר שכתבו. This Must Be the Place I Waited Years to Leave נזכר בבית ספר קפדני ובפחד של ילדות. So Hard הוא שיר ריקוד מהיר על בגידות בזוגיות. How Can You Expect to Be Taken Seriously? לועג לכוכבי פופ שמתחזים לפעילים חברתיים. My October Symphony עוסק בנפילת הקומוניזם, בעיני מלחין רוסי שמאבד את דרכו. Only the Wind ו־To Face the Truth שקטים ונוגים, כמו מכתבים פרטיים.''',
'''Behaviour לא היה מצליח כמו האלבומים הקודמים, אבל עם השנים הוא הפך לאחד האלבומים האהובים ביותר של מעריציהם, ורבים רואים בו את האלבום הטוב ביותר שלהם. Being Boring נחשב לאחד השירים המרגשים של שנות התשעים.''',
'''שמעו את Being Boring לבד, בערב, והקשיבו למילים עד הסוף. ואחר כך שמעו את It's a Sin מ־Actually (אלבום 607), כדי לשמוע כמה הם השתנו בשלוש שנים.''',
], [
('Being Boring', 'שיר יפה ועצוב על נעורים, חברים וזיכרונות, אולי השיר היפה ביותר שכתבו.'),
('This Must Be the Place I Waited Years to Leave', 'זיכרון של בית ספר קפדני ופחד של ילדות, עם צליל אפל.'),
('So Hard', 'שיר ריקוד מהיר וחד על בגידות בזוגיות, עם קצב של מועדון.'),
])

add(673, [
'''הפי מאנדיז כבר הופיעו כאן עם Bummed (אלבום 618), אלבום עכור וממכר. בשנתיים שאחריו הם הפכו לכוכבים, לסמל של סצנת "מאדצ׳סטר" ושל תרבות מסיבות הרייב בבריטניה. Pills 'n' Thrills and Bellyaches, שיצא ב־1990, הוא השיא שלהם, והפיקו אותו פול אוקנפולד וסטיב אוסבורן, שני תקליטנים ומפיקים שהביאו מהמועדונים את הקצב, הבס והרמיקסים. האלבום הגיע למקום הרביעי במצעד הבריטי.''',
'''הצליל קליל, שמשי ומלא גרוב: בס פאנקי, קצב של מועדון, גיטרות של רוק מנצ׳סטר, קלידים, ושירה מדברת ועייפה של שון ריידר, שמספר סיפורים מוזרים ומצחיקים על דמויות מהשכונה, על נוכלים קטנים ועל לילות ארוכים. Step On, גרסה לשיר של ג׳ון קונגוס משנות השבעים, הפך ללהיט, עם הקריאות המשונות והמפורסמות של ריידר. Kinky Afro פותח את האלבום בשיחה מבולבלת בין אב לבנו, על גרוב רגוע ושמח. God's Cop מוזר ומתנדנד, ו־Loose Fit הוא שיר איטי וחלומי, כמו בוקר אחרי מסיבה. Grandbag's Funeral ו־Dennis and Lois מספרים סיפורים קטנים ומוזרים על דמויות מהחיים, בהומור מנצ׳סטרי יבש.''',
'''אחרי האלבום הזה הלהקה נכנסה לתקופה כאוטית, והאלבום הבא שלהם, שהוקלט בברבדוס, כמעט פשט את הרגל של חברת התקליטים פקטורי. אבל Pills 'n' Thrills נשאר אחד האלבומים שמגדירים את בריטניה של תחילת שנות התשעים, ואת הרגע שבו רוק ומוזיקת ריקודים התחברו לגמרי.''',
'''שמעו את Kinky Afro ואחריו את Step On, ותנו לגרוב להוביל. ואם אהבתם, נסו את Ninety של 808 סטייט (אלבום 651), עוד פסקול של מנצ׳סטר הרוקדת. שימו לב לבס: הוא הלב של כל שיר באלבום.''',
], [
('Kinky Afro', 'הפותח, שיחה מבולבלת בין אב לבנו על גרוב רגוע, שמח וממכר.'),
('Step On', 'גרסה לשיר של ג׳ון קונגוס שהפכה ללהיט, עם קצב מועדון וקריאות של ריידר.'),
('Loose Fit', 'שיר איטי וחלומי כמו בוקר אחרי מסיבה, עם בס עמוק וגיטרה רכה.'),
])

add(674, [
'''אחרי ההצלחה העצומה של Faith (אלבום 594), ג׳ורג׳ מייקל היה עייף מהתהילה, מהתדמית של כוכב סקסי ומהקליפים. ב־Listen Without Prejudice Vol. 1, שיצא ב־1990, הוא החליט לתת למוזיקה לדבר: הוא סירב להופיע בקליפים, כמעט לא נתן ראיונות, ואפילו לא שם את תמונתו על העטיפה. במקום זה, על העטיפה מופיע צילום ישן של קהל המון על חוף בקוני איילנד. האלבום שקט, אישי ובוגר, ומלא בשאלות על אמונה, על תהילה ועל העולם.''',
'''הצליל עשיר ושקט: גיטרות אקוסטיות, פסנתר, אורגן, כלי מיתר, קצבים רכים, ומעל הכל הקול של מייקל, חם ומדויק מאי פעם. Praying for Time, הפותח, הוא קינה שקטה על עולם שבו העשירים מתעשרים והעניים נשכחים, עם הדהוד של גוספל. Freedom! '90 הוא שיר קצבי ושמח על השחרור מהתדמית הישנה, ובקליפ שלו, שבו מייקל לא מופיע בכלל, שרות במקומו חמש מהדוגמניות המפורסמות של אותה תקופה. Cowboys and Angels הוא ואלס ג׳אזי ארוך ועצוב על אהבה שלא נענית. Mother's Pride עוסק באמהות ששולחות את בניהן למלחמה, ו־They Won't Go When I Go הוא גרסה מרגשת לשיר של סטיבי וונדר.''',
'''האלבום הצליח מאוד בבריטניה, אבל באמריקה נמכר הרבה פחות מ־Faith, ומייקל האשים את חברת התקליטים שלא קידמה אותו. הוא תבע אותה בבית המשפט, והכרך השני שהובטח בשם האלבום מעולם לא יצא כמו שתוכנן. היום רבים רואים בו את האלבום הטוב והאמיתי ביותר שלו.''',
'''שמעו את Praying for Time בשקט, עם תשומת לב למילים, ואחר כך את Freedom! '90 בקול רם. ואחר כך השוו ל־Faith (אלבום 594), כדי לשמוע מה מייקל השאיר מאחור.''',
], [
('Praying for Time', 'הפותח, קינה שקטה ומרגשת על עולם לא צודק, עם הדהוד של גוספל.'),
("Freedom! '90", 'שיר קצבי ושמח על השחרור מהתדמית הישנה, עם פזמון שקשה לשכוח.'),
('Cowboys and Angels', 'ואלס ג׳אזי ארוך ועצוב על אהבה שלא נענית, עם סקסופון רך.'),
])

add(675, [
'''ניל יאנג כבר הופיע כאן כמה פעמים, לבד ועם להקת קרייזי הורס (אלבומים 135, 185, 245, 318, 340 ו־443). בשנות השמונים הוא התנסה בסגנונות מוזרים, מסינתיסייזרים ועד רוקבילי, ואכזב רבים ממעריציו. Ragged Glory, שיצא ב־1990, הוא החזרה הגדולה שלו לשורשים: הוא אסף את קרייזי הורס, הלהקה הפשוטה והרועשת שלו, והם הקליטו את השירים כמעט בהופעה חיה, באסם בחווה שלו בקליפורניה, עם רעש, פידבק וחופש מלא.''',
'''הצליל עבה, רועש וחם: שתי גיטרות מעוותות, בס פשוט, תופים כבדים, וקולו הגבוה והשבור של יאנג. השירים ארוכים, ורבים מהם נמתחים לעשר דקות של אלתורי גיטרה, שבהם יאנג מכה במיתרים ומשאיר את הפידבק לשרוק. Country Home פותח בשמחה של חזרה הביתה. Love to Burn הוא שיר ארוך ועצוב על אהבה שנגמרת, עם סולואים מתגלגלים. Farmer John הוא גרסה לשיר רוקנרול ישן משנות השישים. Mansion on the Hill מתאר מקום של שלום ומוזיקה, ו־Love and Only Love נמשך עשר דקות, והוא מלחמה בין שנאה לאהבה, בגיטרות. האלבום מסתיים ב־Mother Earth, מזמור לכדור הארץ שמנוגן על גיטרה מעוותת.''',
'''Ragged Glory יצא רגע לפני פריצת הגראנג׳, ולהקות כמו פרל ג׳אם ונירוונה ראו ביאנג את "הסבא של הגראנג׳". הוא הוכיח שיאנג, בן ארבעים וארבע, עדיין רועש וחי כמו הצעירים.''',
'''שמעו את Love to Burn בקול רם, ותנו לגיטרות לקחת את הזמן שלהן. ואחר כך שמעו את Rust Never Sleeps (אלבום 443), עוד אלבום חשמלי סוער של יאנג וקרייזי הורס.''',
], [
('Love to Burn', 'שיר ארוך ועצוב על אהבה שנגמרת, עם סולואים מתגלגלים ופידבק שורק.'),
('Country Home', 'הפותח, שיר שמח על חזרה הביתה, עם שתי גיטרות רועשות ותופים כבדים.'),
('Mansion on the Hill', 'שיר על מקום של שלום ומוזיקה, עם פזמון שמח וגיטרות עבות.'),
])

add(676, [
'''איס קיוב היה הכותב הראשי של אן.דבליו.איי (אלבום 662), אבל ב־1989 עזב את הקבוצה בגלל ויכוחים על כסף. כדי להוכיח שהוא יכול לבד, הוא נסע מלוס אנג׳לס לניו יורק, ועבד עם הבומב סקווד, צוות ההפקה של פאבליק אנמי (אלבום 634). AmeriKKKa's Most Wanted, אלבום הסולו הראשון שלו, יצא ב־1990, ושילב את הסיפורים הקשים של רחובות לוס אנג׳לס עם הצליל הצפוף והזועם של החוף המזרחי.''',
'''הצליל קשה, רועש ומלא שכבות: צפירות, דגימות פאנק, תופים חזקים וקטעי שיחה. קיוב חורז מהר, בזעם ובחוכמה, על גזענות, על המשטרה, על עוני ועל הדרך שבה אמריקה מתייחסת לצעירים שחורים. שם האלבום, עם שלוש האותיות K, הוא רמז מכוון לקו קלוקס קלאן. שיר הנושא מספר על פושע שמרגיש איך זה להיות נרדף. It's a Man's World הוא ויכוח מצחיק וחריף עם הראפרית יו־יו, שעונה לו ולא נותנת לו לנצח. Endangered Species, עם צ׳אק די, מתאר צעירים שחורים כמין בסכנת הכחדה. האלבום ספג גם ביקורת קשה על מילים מבזות כלפי נשים.''',
'''האלבום מכר מיליון עותקים בתוך זמן קצר, ונחשב לאחד מאלבומי הראפ החשובים של התקופה. קיוב הפך בהמשך גם לשחקן קולנוע מצליח, החל מהסרט Boyz n the Hood על החיים בדרום לוס אנג׳לס, ולמפיק ובמאי. האלבום הראה שאפשר לחבר בין ראפ של החוף המערבי לבין ראפ של החוף המזרחי, בתקופה שבה השניים נחשבו לעולמות נפרדים.''',
'''זה אלבום קשה ובוטה, עם מילים אלימות. אם אתם רוצים לנסות, התחילו ב־It's a Man's World, ושימו לב איך יו־יו מנצחת בוויכוח.''',
], [
("AmeriKKKa's Most Wanted", 'שיר הנושא, סיפור של פושע נרדף, על קצב צפוף וזועם של הבומב סקווד.'),
("It's a Man's World", 'ויכוח מצחיק וחריף עם הראפרית יו־יו, שלא נותנת לו לנצח.'),
('Endangered Species (Tales from the Darkside)', 'שיר עם צ׳אק די על צעירים שחורים כמין בסכנת הכחדה.'),
])

add(677, [
'''ג׳יינס אדיקשן כבר הופיעו כאן עם Nothing's Shocking (אלבום 633). Ritual de lo habitual, "טקס של ההרגל" בספרדית, שיצא ב־1990, הוא אלבומם השני והאחרון באותה תקופה, לפני שהתפרקו. גם הפעם פרי פארל עיצב את העטיפה בעצמו, פסל שלו עם שתי נשים, שגרם שוב לחנויות לסרב למכור את האלבום, ולכן יצאה גם עטיפה חלופית, לבנה, עם טקסט על חופש הביטוי. זמן קצר אחרי יציאת האלבום פארל הקים את פסטיבל לולפלוזה, כסיבוב הופעות של פרידה מהלהקה.''',
'''האלבום מחולק לשני חלקים. בחלק הראשון יש שירים קצרים, מהירים ושמחים, כמעט פאנק עם ריקוד. Stop! נפתח בהקדמה בספרדית ופורץ בעוצמה. Been Caught Stealing, הלהיט, הוא שיר משעשע על גניבה מחנויות, עם כלב נובח בהתחלה ובס מקפץ. בחלק השני יש שירים ארוכים, איטיים ועמוקים. Three Days נמשך כמעט אחת־עשרה דקות, ונבנה לאט משקט לסערה עצומה של גיטרות, והוא נחשב ליצירת המופת של הלהקה. Then She Did... הוא שיר אישי מאוד על אובדן, ובו פארל זוכר אישה קרובה שאיבד, ו־Classic Girl הוא שיר אהבה רך ויפה שסוגר את האלבום.''',
'''Been Caught Stealing הגיע למקום הראשון במצעד הרוק האלטרנטיבי באמריקה, והאלבום מכר מיליון עותקים. הוא נחשב לאחד האלבומים שפתחו את הדלת לפריצה הגדולה של הרוק האלטרנטיבי בשנה שאחריו, עם נירוונה (אלבום 685) ופרל ג׳אם (אלבום 697).''',
'''שמעו את Been Caught Stealing כדי לחייך, ואחר כך תנו ל־Three Days את כל אחת־עשרה הדקות שלו, בלי הפרעה. זה מסע שכדאי לעבור עד הסוף.''',
], [
('Been Caught Stealing', 'הלהיט, שיר משעשע על גניבה מחנויות, עם כלב נובח ובס מקפץ.'),
('Three Days', 'אחת־עשרה דקות שנבנות לאט משקט לסערה עצומה, יצירת המופת של הלהקה.'),
('Classic Girl', 'הסוגר, שיר אהבה רך ויפה, עם גיטרות חלומיות וקול מהדהד.'),
])

add(678, [
'''אל.אל. קול ג׳יי, מקווינס שבניו יורק, היה בן שש־עשרה כשהוציא את הסינגל הראשון שלו בחברת דף ג׳אם, החברה של ריק רובין, שהוציאה גם את הביסטי בויז (אלבום 566). בסוף שנות השמונים, אחרי אלבום שנחשב לחלש, רבים אמרו שהקריירה שלו נגמרה. לפי הסיפור, סבתו אמרה לו פשוט "תנצח אותם בנוקאאוט". Mama Said Knock You Out, שיצא ב־1990, בהפקת המפיק הוותיק מרלי מארל, היה התשובה שלו.''',
'''הצליל קשה וחם: דגימות של פאנק וסול ישן, תופים כבדים, בס עמוק, ואל.אל. מתפרץ בחרוזים מהירים, בטוחים ומלאי גאווה. שיר הנושא נפתח במשפט המפורסם "אל תקראו לזה קאמבק", והוא הופך את כל מי שפקפק בו לשק אגרוף, על קצב שמתחיל איטי ומתפוצץ. Around the Way Girl הוא שיר אהבה מתוק לבנות של השכונה, עם דגימה של שיר פופ קליל, והפך ללהיט גדול. The Boomin' System הוא שיר על מערכת שמע חזקה במכונית, שמרעידה את הרחוב. 6 Minutes of Pleasure הוא שיר רך וחלק, ו־Jingling Baby קופצני ומשחקי. To da Break of Dawn הוא קרב מילולי חריף נגד ראפרים יריבים, שמראה כמה אל.אל. נהנה להתחרות.''',
'''שיר הנושא זכה בגראמי, והאלבום מכר יותר משני מיליון עותקים. הוא הוכיח שאל.אל. קול ג׳יי לא הולך לשום מקום, והוא המשיך להצליח במשך שנים, גם כראפר וגם כשחקן טלוויזיה וקולנוע.''',
'''שמעו את Mama Said Knock You Out בקול רם, ושימו לב לרגע שבו הקצב מתפוצץ. ואחר כך את Around the Way Girl, כדי לשמוע את הצד המתוק שלו.''',
], [
('Mama Said Knock You Out', 'שיר הנושא, "אל תקראו לזה קאמבק", על קצב שמתחיל איטי ומתפוצץ.'),
('Around the Way Girl', 'שיר אהבה מתוק לבנות של השכונה, עם דגימה של שיר פופ קליל.'),
("The Boomin' System", 'שיר על מערכת שמע חזקה במכונית, שמרעידה את כל הרחוב.'),
])

add(679, [
'''פאבליק אנמי כבר הופיעו כאן עם It Takes a Nation of Millions to Hold Us Back (אלבום 634). Fear of a Black Planet, שיצא ב־1990, צפוף, ארוך ושאפתני עוד יותר: יותר מעשרים קטעים, שבנויים מאלפי דגימות, צעקות, נאומים וצלילים, בהפקת הבומב סקווד. השם, "פחד מכוכב לכת שחור", מתייחס לפחד של לבנים מפני ערבוב בין גזעים, וצ׳אק די צוחק עליו ותוקף אותו. באותה תקופה הקבוצה הייתה גם במרכז סערה, אחרי ההתבטאויות האנטישמיות של פרופסור גריף, וגם בשירים כאן יש שורות שנתפסו כפוגעות.''',
'''הצליל כמו סערה: שכבות של דגימות שמתנגשות זו בזו, צפירות, תופים, ומעליהם הקול העמוק של צ׳אק די והקריאות של פלייבור פלאב. Fight the Power, ההמנון, נכתב לסרט "עשה את הדבר הנכון" של ספייק לי, וקורא להילחם בכוחות שמדכאים, כולל ביקורת חריפה על גיבורי התרבות האמריקאית הלבנה. 911 Is a Joke, בקולו של פלייבור פלאב, הוא שיר מצחיק וכועס על אמבולנסים שמגיעים מאוחר לשכונות השחורות. Brothers Gonna Work It Out קורא לאחדות. Burn Hollywood Burn, עם איס קיוב (אלבום 676), תוקף את הדרך שבה הוליווד מציגה שחורים.''',
'''האלבום מכר מיליון עותקים זמן קצר מאוד אחרי שיצא, ונבחר לארכיון ההקלטות הלאומי של ספריית הקונגרס האמריקאית. Fight the Power הפך לאחד השירים הפוליטיים החשובים בתולדות המוזיקה האמריקאית.''',
'''שמעו את Fight the Power בקול רם, ואחר כך את 911 Is a Joke כדי לשמוע את ההומור של הקבוצה. ואחר כך חזרו ל־It Takes a Nation (אלבום 634), כדי להשוות.''',
], [
('Fight the Power', 'ההמנון מהסרט של ספייק לי, קריאה עוצמתית להילחם בכוחות המדכאים.'),
('911 Is a Joke', 'שיר מצחיק וכועס של פלייבור פלאב על אמבולנסים שמגיעים מאוחר מדי.'),
('Brothers Gonna Work It Out', 'קריאה לאחדות, על קצב צפוף ומלא שכבות של דגימות.'),
])

add(680, [
'''שינייד או׳קונור גדלה בדבלין שבאירלנד, בילדות קשה ואלימה, ונשלחה כנערה למוסד של נזירות לנערות "בעייתיות". שם גילתה מורה את קולה, ומשם התחילה לשיר. היא התפרסמה עם ראש מגולח, מבט ישיר וכעס שלא הסתירה, ו־I Do Not Want What I Haven't Got, אלבומה השני, יצא ב־1990. היא הפיקה אותו בעצמה, והוא אישי, חשוף ועוצמתי, אלבום של אישה צעירה שמדברת על כאב, על אמהות, על אמונה ועל פרידה.''',
'''הקול של או׳קונור הוא הכל: הוא יכול ללחוש כמו ילדה ולצרוח כמו סערה, לפעמים באותו שיר. Nothing Compares 2 U, שכתב פרינס, הוא שיר געגועים כואב לאהוב שהלך, והקליפ שלו, צילום קרוב של פניה כשדמעה זולגת על לחייה, הפך לאחד הקליפים המפורסמים בעולם. Feel So Different פותח בתפילת השלווה, על רקע כלי מיתר. I Am Stretched on Your Grave הוא שיר אירי עתיק, שמושר על קצב תופים של היפ הופ. Black Boys on Mopeds זועם על מוות של נער שחור בלונדון. The Emperor's New Clothes קצבי ומתריס, ושיר הנושא, הסוגר, מושר כמעט בלי שום ליווי.''',
'''Nothing Compares 2 U הגיע למקום הראשון ביותר מעשרים מדינות, והאלבום מכר מיליוני עותקים. או׳קונור הפכה לכוכבת עולמית, אבל גם לדמות שנויה במחלוקת, שלא פחדה להתעמת עם הכנסייה, עם התקשורת ועם תעשיית המוזיקה. היא מתה ב־2023, ונזכרת היום כאחת הזמרות האמיצות והמרגשות של דורה.''',
'''שמעו את Nothing Compares 2 U, ואחריו את I Am Stretched on Your Grave: הכאב הפרטי והמסורת העתיקה, באותו קול. ואחר כך את שיר הנושא, בשקט מוחלט.''',
], [
('Nothing Compares 2 U', 'שיר געגועים כואב שכתב פרינס, עם אחד הקליפים המפורסמים בעולם.'),
('I Am Stretched on Your Grave', 'שיר אירי עתיק שמושר על קצב תופים של היפ הופ, מפתיע ומרגש.'),
('Feel So Different', 'הפותח, תפילת השלווה על רקע כלי מיתר, וקול שעובר מלחישה לסערה.'),
])

add(681, [
'''א טרייב קולד קווסט הם ארבעה חברים מקווינס שבניו יורק: קיו־טיפ, פייף דוג, עלי שהיד מוחמד וג׳רובי. הם היו חלק מקבוצת "נייטיב טאנגס", יחד עם דה לה סול (אלבום 659) והג׳אנגל ברדרס (אלבום 661), והביאו להיפ הופ ג׳אז, שלווה וחוש הומור. People's Instinctive Travels and the Paths of Rhythm, אלבום הבכורה שלהם, יצא ב־1990, והוא קליל, צבעוני ומשחקי, כמו טיול בשכונה ביום שמש.''',
'''הצליל רגוע וחם: דגימות של ג׳אז, סול, פאנק ורוק, בס עמוק ותופים רכים, וקיו־טיפ חורז בקול גבוה, רך ושלו, שאין לו מקבילה. השירים מספרים סיפורים קטנים ומצחיקים על החיים. Can I Kick It? בנוי על הבס המפורסם של Walk on the Wild Side של לו ריד, והוא שיר משחקי שבו הקהל עונה "כן, אתה יכול". Bonita Applebum הוא שיר אהבה מתוק וחושני, עם סיטאר. I Left My Wallet in El Segundo הוא סיפור מצחיק על נסיעה לקליפורניה שבה נשכח ארנק במסעדה. Footprints ו־Luck of Lucien קלילים ומלאי הומור, ו־Description of a Fool שואל מיהו באמת טיפש.''',
'''האלבום לא נמכר הרבה בהתחלה, אבל עם השנים הוא הפך לקלאסיקה, ופתח את הדרך לאלבום הבא שלהם, The Low End Theory (אלבום 696), שנחשב לאחד מאלבומי ההיפ הופ הגדולים בכל הזמנים. פייף דוג מת ב־2016.''',
'''שמעו את Can I Kick It?, ושימו לב לבס המוכר, ואז שמעו את Walk on the Wild Side של לו ריד. ואחר כך עברו ל־The Low End Theory (אלבום 696).''',
], [
('Can I Kick It?', 'שיר משחקי על הבס המפורסם של לו ריד, שבו הקהל עונה "כן, אתה יכול".'),
('Bonita Applebum', 'שיר אהבה מתוק וחושני, עם סיטאר, בס רך וקול שלו ומלטף.'),
('I Left My Wallet in El Segundo', 'סיפור מצחיק על ארנק שנשכח במסעדה בקליפורניה, עם קצב קופצני.'),
])

add(682, [
'''סוניק יות׳ כבר הופיעו כאן שלוש פעמים, עם EVOL, Sister ו־Daydream Nation (אלבומים 574, 604 ו־630). Goo, שיצא ב־1990, הוא האלבום הראשון שלהם בחברת תקליטים גדולה, גפן, וחברים רבים בסצנה העצמאית חששו שהם "ימכרו את עצמם". הם לא: הצליל נקי וחזק יותר, אבל הרעש, ההומור והמוזרות נשארו. את העטיפה צייר האמן ריימונד פטיבון, בסגנון של קומיקס שחור לבן.''',
'''השירים קצרים וממוקדים יותר מבאלבום הקודם, אבל עדיין מלאים בגיטרות מזמזמות, בכוונונים מוזרים ובפריצות של רעש. Kool Thing, הלהיט, שקים גורדון שרה, הוא שיר מצחיק ומתריס על ראיון שערכה פעם עם הראפר אל.אל. קול ג׳יי (אלבום 678), וצ׳אק די מפאבליק אנמי מצטרף אליה באמצע לשיחה משועשעת. Dirty Boots, הפותח, נבנה לאט משקט לסערה מתוקה. Tunic (Song for Karen) הוא שיר עצוב ומוזר על הזמרת קארן קרפנטר, שמתה מאנורקסיה. Disappearer ו־Mote מלאים בגיטרות מהפנטות, ו־Mildred Pierce הוא פרץ קצר של רעש טהור. Cinderella's Big Score ו־My Friend Goo קצביים ומשועשעים, ומראים את הצד הקליל של הלהקה.''',
'''Goo היה האלבום המצליח ביותר של סוניק יות׳ עד אז, והקליפים שלו הוצגו ב־MTV. החברים גם עזרו לנירוונה (אלבום 685) לחתום באותה חברת תקליטים, ולקחו אותם איתם לסיבובי הופעות, רגע לפני שנירוונה כבשו את העולם. גם הקליפים של התקופה, שצולמו בתקציב קטן, הפכו לחלק מהתרבות של הרוק האלטרנטיבי.''',
'''שמעו את Kool Thing, ושימו לב לשיחה המצחיקה עם צ׳אק די. ואחר כך את Tunic, כדי לשמוע את הצד העצוב והמוזר של קים גורדון.''',
], [
('Kool Thing', 'הלהיט, שיר מצחיק ומתריס של קים גורדון, עם צ׳אק די בשיחה משועשעת.'),
('Dirty Boots', 'הפותח, שיר שנבנה לאט משקט לסערה מתוקה של גיטרות מזמזמות.'),
('Tunic (Song for Karen)', 'שיר עצוב ומוזר על הזמרת קארן קרפנטר, עם גיטרות מהפנטות.'),
])

add(683, [
'''רייד באו מאוקספורד, ארבעה חברים שהכירו בבית ספר לאמנות: מארק גרדנר ואנדי בל, שכתבו ושרו יחד, הבסיסט סטיב קוורלט והמתופף לורנס קולברט, שניגן בעוצמה רבה. הם חתמו בחברת קריאיישן, הבית של מיי בלאדי ולנטיין (אלבום 622) ושל הג׳יזס אנד מרי צ׳יין, והפכו לאחת הלהקות הבולטות של הסגנון שנקרא "שוגייז", שבו הנגנים עומדים ובוהים בדוושות האפקטים שלרגליהם. Nowhere, אלבום הבכורה שלהם, יצא ב־1990, עם צילום של גל ענק על העטיפה.''',
'''הצליל הוא כמו הגל שעל העטיפה: גיטרות רועשות, מעוותות ומהדהדות, שבונות קיר של צליל, ומתחתיהן מנגינות מתוקות וקולות רכים, שרים יחד בהרמוניה שמזכירה את הבירדס ואת הביטלס של שנות השישים. התופים של קולברט חזקים ומהירים, ונותנים לשירים אנרגיה של להקת רוק אמיתית. Seagull, הפותח, נשמע כמו סערה של גיטרות, עם בס שמזכיר את הביטלס. Vapour Trail, הסוגר, הוא שיר אהבה יפה ופשוט, שמסתיים ברביעיית כלי מיתר שקטה ומרגשת. Dreams Burn Down איטי וחלומי, Polar Bear מהפנט, ו־In a Different Place שקט ומרחף. כמה מהשירים ארוכים ומתפתחים לאט, עם קטעי גיטרה שנבנים לשיא ואז שוקטים.''',
'''Nowhere נחשב לאחד האלבומים החשובים של השוגייז, ו־Vapour Trail נשאר אחד השירים האהובים של הסגנון. רייד התפרקו באמצע שנות התשעים, ואנדי בל הצטרף אחר כך כבסיסט לאואזיס. ב־2014 הלהקה חזרה להופיע ולהקליט.''',
'''שמעו את Vapour Trail עד הסוף, וחכו לכלי המיתר. ואחר כך שמעו את Loveless של מיי בלאדי ולנטיין (אלבום 684), שבו השוגייז הגיע לקצה.''',
], [
('Vapour Trail', 'הסוגר, שיר אהבה יפה ופשוט שמסתיים ברביעיית כלי מיתר שקטה ומרגשת.'),
('Seagull', 'הפותח, סערה של גיטרות ובס שמזכיר את הביטלס, עם תופים עוצמתיים.'),
('Dreams Burn Down', 'שיר איטי וחלומי, עם גיטרות שנשרפות לאט ושירה רכה בהרמוניה.'),
])

add(684, [
'''מיי בלאדי ולנטיין כבר הופיעו כאן עם Isn't Anything (אלבום 622). Loveless, שיצא ב־1991, הוא אחד האלבומים המיתולוגיים ביותר של הרוק. קווין שילדס, שהיה פרפקציוניסט קיצוני, הקליט אותו במשך כשנתיים, בכמעט עשרים אולפנים שונים, והחליף מהנדסי סאונד שוב ושוב. לפי הסיפורים, ההקלטות כמעט הביאו לפשיטת הרגל של חברת התקליטים קריאיישן, למרות ששילדס עצמו טוען שהעלות הייתה נמוכה יותר מכפי שמספרים.''',
'''הצליל לא דומה לשום דבר אחר: גיטרות שנשמעות כמו גלים, כמו רוח, כמו מנועים או כמו חלום מעורפל, שמתעקמות, מתמזגות ומתנפחות. מתחת לרעש יש מנגינות יפות מאוד, ושילדס ובלינדה בוצ׳ר שרים בלחישה, כאילו מתוך שינה, כך שהמילים כמעט נבלעות. Only Shallow, הפותח, נפתח בפיצוץ של תופים וגיטרות שנשמעות כמו צעקות. When You Sleep הוא שיר פופ מתוק וחמים, מתחת לשכבות של צליל. Sometimes, שהופיע בסרט "אבודים בטוקיו", הוא שיר רך ונוגה. To Here Knows When נשמע כמו חלום, ו־Soon, הסוגר, הוא שיר ריקוד מהפנט, עם קצב של מועדון. שילדס גם השתמש בדגימות של פידבק ובצלילים מעובדים, כך שקשה לדעת מה מנוגן ומה מעובד במחשב.''',
'''Loveless נחשב לאחד האלבומים הגדולים של שנות התשעים, ולשיא של השוגייז. בריאן אינו אמר על Soon שהוא קבע סטנדרט חדש לפופ. האלבום הבא של הלהקה יצא רק ב־2013, עשרים ושתיים שנה אחר כך.''',
'''שמעו את Loveless עם אוזניות טובות, בקול רם ובחושך. אל תנסו להבין את המילים, ותנו לגלים לשטוף אתכם, מההתחלה ועד Soon בסוף. שימו לב גם לתופים: חלקם דגימות, וחלקם מנוגנים, והם נותנים לגלים את הקצב.''',
], [
('Only Shallow', 'הפותח, פיצוץ של תופים וגיטרות שנשמעות כמו צעקות, ולחישה רכה באמצע.'),
('When You Sleep', 'שיר פופ מתוק וחמים, שמתחבא מתחת לשכבות עבות של גיטרות.'),
('Soon', 'הסוגר, שיר ריקוד מהפנט עם קצב של מועדון וגיטרות כמו גלים.'),
])

add(685, [
'''נירוונה קמו באברדין, עיירת עצים קטנה ועגומה במדינת וושינגטון, ובמרכזם קורט קוביין, זמר וכותב שירים שאהב פאנק, את הביטלס ואת הפיקסיז (אלבומים 623 ו־655). לצדו ניגנו הבסיסט קריס נובוסליק והמתופף החדש דייב גרוהל. אחרי אלבום ראשון בחברה העצמאית סאב פופ, הם חתמו בחברת גפן, בעזרת סוניק יות׳ (אלבום 682), והקליטו את Nevermind עם המפיק בוץ׳ ויג. האלבום יצא בספטמבר 1991, וחברת התקליטים קיוותה למכור כמה מאות אלפי עותקים בלבד.''',
'''המוזיקה מחברת את הרעש והזעם של הפאנק עם מנגינות פופ מושלמות: בתים שקטים, פזמונים מתפוצצים, גיטרה עבה, תופים עוצמתיים, וקולו של קוביין, צרוד, שבור וצועק. Smells Like Teen Spirit, הפותח, נשמע כמו המנון של דור שלם, עם ריף של ארבעה אקורדים ומילים מבולבלות ואירוניות. Come as You Are איטי ומהפנט, עם גיטרה שנשמעת כמו מים. In Bloom לועג לאנשים ששרים את השירים בלי להבין אותם. Lithium עובר בין שקט לצעקה, ו־Something in the Way, הסוגר, שקט, עצוב ונוגה, עם צ׳לו.''',
'''Nevermind שינה את המוזיקה בבת אחת: בינואר 1992 הוא הדיח מהמקום הראשון במצעד האמריקאי את מייקל ג׳קסון, והפך את הרוק האלטרנטיבי למוזיקה של כולם. על העטיפה מופיע תינוק ששוחה במים אחרי שטר של דולר. קוביין, שלא עמד בלחץ התהילה, מת ב־1994, בגיל עשרים ושבע, ודייב גרוהל הקים אחר כך את פו פייטרס.''',
'''שמעו את Smells Like Teen Spirit, ואחריו את Something in the Way: ההתחלה והסוף של אחד האלבומים החשובים בתולדות הרוק. ואחר כך חזרו ל־Doolittle של הפיקסיז (אלבום 655), כדי לשמוע ממי קוביין למד.''',
], [
('Smells Like Teen Spirit', 'הפותח, ההמנון של דור שלם, עם ריף של ארבעה אקורדים ושקט שמתפוצץ.'),
('Come as You Are', 'שיר איטי ומהפנט, עם גיטרה שנשמעת כמו מים וקול צרוד ורך.'),
('Something in the Way', 'הסוגר, שקט, עצוב ונוגה, עם גיטרה אקוסטית וצ׳לו.'),
])

add(686, [
'''קראודד האוס קמו במלבורן שבאוסטרליה, ובמרכזם עמד ניל פין, זמר וכותב שירים מניו זילנד, שהתחיל את דרכו בלהקה של אחיו הגדול, טים, בשם ספליט אנז. לצדו ניגנו הבסיסט ניק סימור והמתופף פול הסטר, שהיה גם הליצן של הלהקה. Woodface, שיצא ב־1991, הוא אלבומם השלישי, ובו הצטרף אליהם גם טים פין, שכתב ושר עם אחיו כמה מהשירים. ההרמוניות של שני האחים הן הלב של האלבום.''',
'''זה פופ־רוק מלודי וחם, עם גיטרות אקוסטיות וחשמליות, קלידים, קולות רקע עשירים ומנגינות שנכנסות לראש ולא יוצאות. המילים מדברות על אהבה, על מזג אוויר, על הזמן שעובר ועל מצבי רוח שמשתנים. Weather with You, הלהיט, הוא שיר רגוע ושמשי על כך שאת מזג האוויר אתה לוקח איתך לכל מקום. Four Seasons in One Day הוא שיר יפה ונוגה על עיר שבה מזג האוויר משתנה בתוך יום אחד, כמו הרגשות. Fall at Your Feet היא בלדה רכה ומרגשת על אהבה ועל חולשה. Chocolate Cake הוא שיר סאטירי ומצחיק על אמריקה, ו־It's Only Natural קליל ושמח.''',
'''באמריקה האלבום לא הצליח כמו קודמיו, אבל בבריטניה ובאירופה הוא הפך את הלהקה לכוכבת, ו־Weather with You הגיע לעשירייה הראשונה. טים פין עזב באמצע סיבוב ההופעות, ופול הסטר מת ב־2005. רבים רואים ב־Woodface את האלבום הטוב ביותר של הלהקה, מלא בשירים מושלמים.''',
'''שמעו את Four Seasons in One Day ואחריו את Weather with You: שני שירים על מזג אוויר, אחד עצוב ואחד שמח. ואם אהבתם, נסו את 16 Lovers Lane של הגו־ביטווינס (אלבום 619), עוד פופ אוסטרלי יפה.''',
], [
('Weather with You', 'הלהיט, שיר רגוע ושמשי על כך שאת מזג האוויר לוקחים לכל מקום.'),
('Four Seasons in One Day', 'שיר יפה ונוגה על עיר שבה מזג האוויר משתנה כמו הרגשות.'),
('Fall at Your Feet', 'בלדה רכה ומרגשת על אהבה ועל חולשה, עם קול חם ורך.'),
])

add(687, [
'''סייפרס היל קמו בסאות׳ גייט, ליד לוס אנג׳לס, שלושה חברים ממוצא לטיני: בי־ריל, עם קול גבוה ואפי שאין לו מקבילה, סן דוג, שחורז בקול עמוק ולפעמים בספרדית, והמפיק די ג׳יי מאגס. הם הביאו להיפ הופ את התרבות הלטינית של לוס אנג׳לס, וגם תמיכה גלויה ובולטת בלגליזציה של מריחואנה, שהפכה לחלק מהתדמית שלהם. אלבום הבכורה שלהם יצא ב־1991.''',
'''הצליל של מאגס אפל, עשן ואיטי: תופים כבדים ומתנדנדים, בס עמוק, דגימות של פאנק, סול ורוק, וצלילים מוזרים של צופרים ושל יללות. מעל זה בי־ריל חורז בקולו האפי הגבוה, וסן דוג עונה לו בקול עמוק. השירים מתארים את החיים ברחובות, את הכנופיות, את המשטרה ואת המסיבות, ולפעמים הם אלימים ובוטים. Hand on the Pump בנוי על דגימה של שיר סול ישן, והוא אחד השירים המוכרים שלהם. Latin Lingo משלב אנגלית וספרדית, ומתגאה בזהות הלטינית. The Phuncky Feel One קופצני וכיפי, ו־Real Estate מספר על כבוד ועל שכונה.''',
'''האלבום מכר מיליון עותקים, וסייפרס היל הפכו לאחת הקבוצות המצליחות של שנות התשעים, עם הלהיט Insane in the Brain שבא אחריו. הם פתחו את הדלת לראפרים לטיניים רבים, והצליל האפל והעשן של מאגס השפיע על הפקות היפ הופ רבות. הקול האפי של בי־ריל הפך לאחד הקולות המזוהים ביותר בהיפ הופ.''',
'''שמעו את Latin Lingo, ושימו לב איך השפות מתערבבות. ואחר כך נסו את Straight Outta Compton של אן.דבליו.איי (אלבום 662), עוד צד של לוס אנג׳לס בשנים שלפני.''',
], [
('Latin Lingo', 'שיר שמשלב אנגלית וספרדית, ומתגאה בזהות הלטינית של לוס אנג׳לס.'),
('Hand on the Pump', 'אחד השירים המוכרים שלהם, בנוי על דגימה של שיר סול ישן.'),
('The Phuncky Feel One', 'שיר קופצני וכיפי, עם בס עמוק וקולו האפי והגבוה של בי־ריל.'),
])

add(688, [
'''ג׳וליאן קופ התפרסם בתחילת שנות השמונים כזמר של הטירדרופ אקספלודס מליברפול, להקת פוסט־פאנק פסיכדלית, ואחר כך התחיל קריירת סולו מוזרה, מלאת עליות ומורדות. הוא אדם של רעיונות גדולים: מוזיקה, אקולוגיה, היסטוריה עתיקה ורוחניות. Peggy Suicide, שיצא ב־1991, הוא אלבום כפול, שבו "פגי סואיסייד" היא בעצם כדור הארץ, שמתאבד לאט בגלל זיהום, מכוניות וחמדנות האדם.''',
'''המוזיקה מחברת רוק פסיכדלי של שנות השישים, קראוטרוק גרמני, פאנק ופולק: גיטרות חשמליות ארוכות, תופים מהפנטים, קלידים, וקולו העמוק והתיאטרלי של קופ. האלבום ארוך ומגוון, עם שירים קצרים וקליטים לצד קטעים ארוכים ומשתוללים. Beautiful Love, הסינגל, הוא שיר אהבה קליל ושמח, עם מנגינה פשוטה ויפה. East Easy Rider מהיר וסוחף, כמו נסיעה בכביש פתוח. Safesurfer הוא שיר ארוך ומהפנט, שנבנה לאט עד לשיא של גיטרות. Drive, She Said מתאר את התרבות של המכוניות, שקופ שנא. יש באלבום גם שירים שנכתבו בהשראת ההפגנות הגדולות בלונדון נגד מס הגולגולת של ת׳אצ׳ר. קופ גם ניגן בעצמו על כמה כלים, והקליט את רוב השירים עם להקה קטנה וקבועה, שנשמעת חמה וחיה.''',
'''Peggy Suicide נחשב לאחד האלבומים הטובים של קופ, ולאחד האלבומים הירוקים והפוליטיים הראשונים של הרוק הבריטי. בהמשך קופ כתב ספרים על אתרים עתיקים ועל מוזיקה גרמנית, והפך לדמות אגדית ומיוחדת של התרבות הבריטית. בשנים שאחר כך הוא גם תמך בגלוי במאבקים של פעילי סביבה ברחבי בריטניה.''',
'''זה אלבום ארוך, אז שמעו אותו בכמה פעמים. התחילו ב־Beautiful Love ו־East Easy Rider, ואחר כך תנו ל־Safesurfer לקחת אתכם.''',
], [
('Beautiful Love', 'הסינגל, שיר אהבה קליל ושמח עם מנגינה פשוטה ויפה.'),
('East Easy Rider', 'שיר מהיר וסוחף כמו נסיעה בכביש פתוח, עם גיטרות ותופים מהפנטים.'),
('Safesurfer', 'שיר ארוך ומהפנט שנבנה לאט, עד לשיא סוער של גיטרות.'),
])

add(689, [
'''גאנג סטאר הם צמד: הראפר גורו, שגדל בבוסטון כבן של שופט, והמפיק די ג׳יי פרימייר, שבא מיוסטון שבטקסס. השניים נפגשו בניו יורק, והפכו לאחד הצמדים החשובים בתולדות ההיפ הופ. Step in the Arena, שיצא ב־1991, הוא אלבומם השני, ובו פרימייר מצא את הצליל שלו: חתיכות קטנות של ג׳אז, סול ופאנק, חתוכות ומחוברות מחדש, עם תופים יבשים וחדים, וסקרץ׳ על הפטיפונים שהופך לפזמון.''',
'''גורו חורז בקול שקט, עמוק ומונוטוני כמעט, כמו מורה חכם או מספר סיפורים ברחוב, בלי צעקות ובלי התלהבות מזויפת. המילים מדברות על כבוד, על חוכמה, על הרחוב ועל הדרך לא ליפול לפשע. Just to Get a Rep, אחד השירים המפורסמים שלהם, מספר סיפור על נער שמשדד אנשים רק כדי לבנות לעצמו מוניטין, ומסתיים בצורה עצובה. Step in the Arena, שיר הנושא, הוא הזמנה להתחרות בזירה של הראפ. Form of Intellect ו־Check the Technique מלאים בדגימות של ג׳אז, ו־Lovesick הוא שיר רך על אהבה ועל מוזיקה. Who's Gonna Take the Weight? הוא שיר על אחריות, על קצב חד ודגימות קצרות של ג׳אז.''',
'''הצליל של די ג׳יי פרימייר השפיע על ההיפ הופ של ניו יורק בשנות התשעים יותר מכמעט כל מפיק אחר, והוא הפיק אחר כך לראפרים רבים. גורו יצר בהמשך את סדרת האלבומים Jazzmatazz, שבה ניגן עם נגני ג׳אז אמיתיים, ומת ב־2010.''',
'''שמעו את Just to Get a Rep עד הסוף, והקשיבו לסיפור. ואחר כך נסו את The Low End Theory של א טרייב קולד קווסט (אלבום 696), עוד חיבור יפה בין ג׳אז להיפ הופ מאותה שנה.''',
], [
('Just to Get a Rep', 'סיפור על נער שמשדד רק כדי לבנות לעצמו מוניטין, ומסתיים בעצב.'),
('Step in the Arena', 'שיר הנושא, הזמנה לזירה של הראפ, עם סקרץ׳ שהופך לפזמון.'),
('Form of Intellect', 'שיר מלא בדגימות של ג׳אז, עם קולו השקט והחכם של גורו.'),
])

add(690, [
'''אם סי סולאר, שנולד בשם קלוד מ׳בארלי, נולד בדקר שבסנגל, וגדל בפרברים של פריז. הוא למד שפות ופילוסופיה באוניברסיטה, ואהב משחקי מילים, ספרות והיפ הופ אמריקאי. Qui sème le vent récolte le tempo, "מי שזורע רוח קוצר טמפו", משחק מילים על הפתגם "מי שזורע רוח קוצר סערה", יצא ב־1991, והיה אחד האלבומים הראשונים שהפכו את הראפ הצרפתי למוזיקה פופולרית ומכובדת.''',
'''הצליל רך ומלא ג׳אז: דגימות של ג׳אז, סול ופאנק, תופים קלים, בס מתגלגל, והקול השקט, המתנגן והחכם של סולאר, שנשמע כמעט כמו שיחה. המפיק ג׳ימי ג׳יי בנה את הקצבים. המילים מלאות במשחקי מילים, בדימויים ובהומור, ורבים רואים בסולאר משורר לא פחות מראפר. Bouge de là, הלהיט הראשון, מספר בהומור על בחור שמנסה לפלס דרך בקהל, ונשען על דגימה של להקת פאנק בריטית. Caroline הוא שיר אהבה רך ועצוב על אהבה ראשונה שאבדה. Victime de la mode צוחק על אנשים שעוקבים אחרי האופנה, ושיר הנושא שקט וחכם. La musique adoucit les mœurs, "המוזיקה מעדנת את המידות", הוא שיר רגוע על כוחה של המוזיקה, על קצב ג׳אזי.''',
'''האלבום מכר מאות אלפי עותקים בצרפת, וסולאר הפך לכוכב, ולאחד הראפרים האהובים בעולם דובר הצרפתית. הוא שיתף פעולה עם גורו מגאנג סטאר (אלבום 689), וממשיך להקליט ולהופיע עד היום, כמשורר ראפ מכובד.''',
'''גם אם אתם לא מבינים צרפתית, שמעו את Caroline ואת Bouge de là, ותנו לצליל של השפה להוביל אתכם. אחר כך תוכלו לחפש את התרגום, ולגלות כמה משחקי מילים פספסתם.''',
], [
('Bouge de là, Part 1', 'הלהיט הראשון, סיפור מצחיק על בחור שמפלס דרך בקהל, על דגימה פאנקית.'),
('Caroline', 'שיר אהבה רך ועצוב על אהבה ראשונה שאבדה, עם פסנתר וקול שקט.'),
('Victime de la mode', 'שיר משעשע שצוחק על אנשים שעוקבים אחרי האופנה בלי לחשוב.'),
])

add(691, [
'''ג׳ה וובל, שנולד בשם ג׳ון וורדל במזרח לונדון, התפרסם כבסיסט של פאבליק אימג׳ לימיטד (אלבומים 406 ו־448), עם בס עמוק ומרעיד בסגנון של דאב ג׳מייקני. אחרי שעזב את הלהקה, הוא עבר תקופה קשה, ואפילו עבד כנהג ברכבת התחתית של לונדון. בסוף שנות השמונים הוא הקים את Invaders of the Heart, להקה שמחברת את הבס שלו עם מוזיקה מכל העולם: ערבית, אפריקאית, הודית וקלטית. Rising Above Bedlam, שיצא ב־1991, הוא הפריצה שלה.''',
'''במרכז תמיד נמצא הבס של וובל, עמוק, איטי ומהפנט, שמרגישים אותו בבטן. מעליו יש גיטרות, כלי הקשה מכל העולם, חליל, כינור וקולות מיוחדים. הזמרת נטשה אטלס, ממוצא מצרי, שגדלה בבלגיה, שרה בערבית, וקולה מוסיף לאלבום צבע של המזרח התיכון. Visions of You, עם שינייד או׳קונור (אלבום 680), הוא שיר רך וחלומי, שהצליח גם במצעד הבריטי. Bomba מחבר מקצבים ערביים עם דאב. Relight the Flame ו־Everyman's an Island מהפנטים ושקטים, כמו מדיטציה.''',
'''האלבום הראה לקהל הבריטי שמוזיקה עולמית יכולה להתחבר בטבעיות עם דאב, רוק ומוזיקת ריקודים. נטשה אטלס התפרסמה בזכותו, והמשיכה לקריירה מצליחה כזמרת שמחברת מזרח ומערב. וובל המשיך להקליט עשרות אלבומים, ונחשב לאחד הבסיסטים המיוחדים בבריטניה.''',
'''שמעו את Visions of You עם אוזניות, ושימו לב לבס: הוא מוביל את השיר כולו. ואחר כך שמעו את Metal Box של פאבליק אימג׳ (אלבום 448), כדי לשמוע מאיפה הבס הזה בא. שימו לב גם לקולה של נטשה אטלס ב־Bomba, ולאיך הוא נפגש עם הבס הלונדוני.''',
], [
('Visions of You', 'שיר רך וחלומי עם שינייד או׳קונור, שהפך ללהיט, על בס עמוק ומהפנט.'),
('Bomba', 'מקצבים ערביים שפוגשים דאב, עם קולה של נטשה אטלס.'),
("Everyman's an Island", 'שיר מהפנט ושקט כמו מדיטציה, עם בס איטי וכלי הקשה עדינים.'),
])

add(692, [
'''הרד הוט צ׳ילי פפרז קמו בלוס אנג׳לס ב־1983, וחיברו פאנק, פאנק־רוק וראפ בהופעות פרועות. הגיטריסט המקורי שלהם, הלל סלובק, שנולד בחיפה, מת ב־1988, והלהקה כמעט התפרקה. הם מצאו גיטריסט צעיר בשם ג׳ון פרושיאנטה, מעריץ שלהם, ומתופף חדש, צ׳אד סמית׳. Blood Sugar Sex Magik, שיצא ב־1991, הופק על ידי ריק רובין, והוקלט באחוזה ישנה בלוס אנג׳לס, שלפי השמועות רדפו בה רוחות, והלהקה גרה בה במשך כל ההקלטות.''',
'''הצליל פשוט ויבש: בס פאנקי ומקפץ של פלי, גיטרה עדינה, מדויקת וחסכונית של פרושיאנטה, תופים חזקים, ושירה וראפ של אנתוני קידיס. לצד שירי פאנק מהירים, יש כאן גם שירים רכים ושקטים, שהיו חדשים ללהקה. Under the Bridge, הלהיט הגדול, הוא שיר בודד ועצוב על לוס אנג׳לס ועל הימים הקשים שקידיס עבר, והעיר היא החבר היחיד שלו. Give It Away הוא שיר פאנק מטורף ומקפץ על נדיבות ועל נתינה, שזכה בגראמי. Breaking the Girl הוא שיר מוזר ויפה עם כלי הקשה מאולתרים. My Lovely Man הוא שיר פרידה לחבר שמת, הלל סלובק.''',
'''האלבום מכר יותר מעשרה מיליון עותקים, והפך את הלהקה לאחת הגדולות בעולם. פרושיאנטה לא עמד בלחץ ההצלחה ועזב באמצע סיבוב ההופעות, אבל חזר אחר כך ללהקה, כמה פעמים. Under the Bridge נשאר אחד השירים המזוהים ביותר עם שנות התשעים.''',
'''שמעו את Under the Bridge בשקט, ואחר כך את Give It Away בקול רם. ואם אתם רוצים לשמוע מאיפה הפאנק־רוק שלהם בא, נסו את Truth and Soul של פישבון (אלבום 613), חבריהם מלוס אנג׳לס.''',
], [
('Under the Bridge', 'הלהיט, שיר בודד ועצוב על לוס אנג׳לס, שבו העיר היא החבר היחיד.'),
('Give It Away', 'שיר פאנק מטורף ומקפץ על נתינה ונדיבות, שזכה בפרס גראמי.'),
('My Lovely Man', 'שיר פרידה לחבר שמת, הגיטריסט הלל סלובק, שנולד בחיפה.'),
])

add(693, [
'''אייס־טי, שנולד בשם טרייסי מארו בניו ג׳רזי וגדל בלוס אנג׳לס אחרי שאיבד את הוריו בילדותו, היה מהראשונים שהביאו לראפ של החוף המערבי סיפורים על חיי הכנופיות והרחוב, כבר באמצע שנות השמונים. O.G. Original Gangster, שיצא ב־1991, הוא אלבומו הרביעי, וארוך במיוחד: עשרים וארבעה קטעים. הכותרת, "גנגסטר מקורי", היא הצהרה שהוא היה שם לפני כולם, לפני אן.דבליו.איי (אלבום 662) ואיס קיוב (אלבום 676).''',
'''הצליל קשה ומלא בשכבות: דגימות של פאנק ושל רוק, תופים כבדים וסירנות, ואייס־טי חורז בקול עמוק, איטי ובטוח, כמו מספר סיפורים מבוגר. השירים מספרים על החיים ברחוב, על כלא, על כסף ועל המחיר שמשלמים. New Jack Hustler, מתוך הסרט "ניו ג׳ק סיטי", שבו אייס־טי שיחק שוטר, מתאר סוחר סמים שלא יכול לעצור. The Tower הוא סיפור קשה על החיים בבית כלא. Mind over Matter הוא שיר על כוח הרצון. באלבום גם מוצגת לראשונה להקת המטאל שלו, בודי קאונט, שחיברה ראפ ומטאל ועוררה שנה אחר כך סערה ציבורית גדולה בגלל שיר מחאה בוטה. Lifestyles of the Rich and Infamous לועג לאנשים שמתהדרים בכסף שהשיגו בדרכים עקומות.''',
'''האלבום נחשב לאחד הטובים של אייס־טי, ולאחד האלבומים החשובים של הגנגסטה ראפ. בהמשך הוא הפך לשחקן מצליח מאוד, ובמשך יותר מעשרים שנה גילם דווקא שוטר בסדרת הטלוויזיה "חוק וסדר".''',
'''זה אלבום ארוך, קשה ובוטה. אם אתם רוצים לנסות, התחילו ב־New Jack Hustler, ושימו לב איך אייס־טי מספר את הסיפור מבפנים, כמו סופר. שימו לב גם לקטעים הקצרים בין השירים, שמחברים את האלבום כמו סרט.''',
], [
('New Jack Hustler', 'שיר מתוך סרט, על סוחר סמים שלא יכול לעצור, מסופר מבפנים.'),
('The Tower', 'סיפור קשה ומוחשי על החיים בבית כלא, על קצב איטי ומאיים.'),
('Mind over Matter', 'שיר על כוח הרצון ועל ההחלטה לא ליפול, בקול עמוק ובטוח.'),
])

add(694, [
'''מאדהאני כבר הופיעו כאן עם Superfuzz Bigmuff (אלבום 616). Every Good Boy Deserves Fudge, שיצא ב־1991, הוא אלבומם השני באורך מלא, והאחרון בחברת סאב פופ, שהייתה אז כמעט פושטת רגל. הם הקליטו אותו בזול, על ציוד ישן של שמונה ערוצים, וזה בדיוק מה שנותן לו את הצליל החם והמלוכלך. השם לקוח מכלל זיכרון של שיעורי מוזיקה, שבעזרתו ילדים לומדים את שמות התווים על החמשה.''',
'''הצליל מחוספס וגולמי: גיטרות מעוותות, בס עבה, תופים פרועים, וגם אורגן ישן ומפוחית, שמוסיפים לו טעם של רוק משנות השישים. מארק ארם צועק ושר בקול צרוד ומלא הומור עוקצני. Generation Genocide פותח את האלבום בקטע כלי קצר ומאיים, ומיד אחריו Let It Slide, מהיר ומלא אנרגיה. Good Enough הוא שיר רך יותר, עם גיטרה אקוסטית ומנגינה יפה. Into the Drink ו־Who You Drivin' Now? מהירים ומקפצים, ו־Thorn כבד ואיטי. גם Shoot the Moon ו־Check-Out Time מראים כמה הלהקה יודעת לשלב בין רעש להומור ולמנגינה.''',
'''כמה חודשים אחרי שהאלבום יצא, נירוונה (אלבום 685) הוציאו את Nevermind, וסיאטל הפכה למרכז עולם הרוק. מאדהאני חתמו בחברה גדולה, אבל אף פעם לא הגיעו להצלחה של חבריהם, ובחרו להמשיך לנגן את מה שהם אוהבים, באותו הומור ובאותו רעש, עד היום.''',
'''שמעו את Let It Slide בקול רם, ואחר כך את Good Enough, כדי לשמוע את הצד הרך שלהם. ואחר כך השוו ל־Nevermind של נירוונה (אלבום 685), שיצא כמה חודשים אחר כך. שימו לב לאורגן ולמפוחית: הם נותנים לרעש טעם של רוק ישן.''',
], [
('Let It Slide', 'שיר מהיר ומלא אנרגיה, עם גיטרות מעוותות ושירה צרודה.'),
('Good Enough', 'שיר רך יותר, עם גיטרה אקוסטית ומנגינה יפה מתחת לחספוס.'),
('Into the Drink', 'שיר מהיר ומקפץ, עם גיטרות מעוותות והומור עוקצני של מארק ארם.'),
])

add(695, [
'''פאבליק אנמי כבר הופיעו כאן פעמיים, עם It Takes a Nation of Millions (אלבום 634) ועם Fear of a Black Planet (אלבום 679). Apocalypse 91... The Enemy Strikes Black, שיצא ב־1991, הוא אלבומם הרביעי, והוא ממשיך באותה דרך: ראפ פוליטי, זועם וצפוף, עם הקול העמוק של צ׳אק די והקריאות של פלייבור פלאב. הפעם ההפקה קצת יותר נקייה וחשופה, והקצבים מהירים, קשים וממוקדים יותר, כמעט כמו של רוק.''',
'''השירים עוסקים בהיסטוריה של העבדות, בתקשורת, בסמים, בפוליטיקה ובכבוד. By the Time I Get to Arizona הוא שיר מחאה נגד מדינת אריזונה, שסירבה אז להכיר ביום הזיכרון למרטין לותר קינג, והקליפ הבוטה שלו עורר סערה. Can't Truss It מחבר בין העבדות לבין המצב של השחורים באמריקה של שנות התשעים, על קצב פאנקי מקפץ. Shut 'Em Down קורא לאנשים להחרים חברות שלא מחזירות דבר לקהילה. Nighttrain מהיר ועצבני. וגם יש כאן גרסה חדשה ל־Bring the Noise, שהוקלטה יחד עם להקת המטאל אנת׳ראקס (אלבום 585), אחד החיבורים הראשונים והמפורסמים של ראפ ומטאל.''',
'''האלבום הגיע למקום הרביעי במצעד האמריקאי, הגבוה ביותר שלהם, והראה שהקבוצה עדיין בשיא כוחה. הסיבוב המשותף עם אנת׳ראקס פתח את הדלת לחיבורים רבים בין ראפ לרוק בשנים שאחר כך. צ׳אק די המשיך להיות אחד הקולות הפוליטיים החשובים בהיפ הופ, ופעיל בנושאים חברתיים עד היום.''',
'''שמעו את Bring the Noise עם אנת׳ראקס, ואחריו את הגרסה המקורית מ־It Takes a Nation (אלבום 634). ואחר כך את Can't Truss It, אחד השירים הקצביים והחזקים שלהם.''',
], [
("Can't Truss It", 'שיר שמחבר בין העבדות לבין שנות התשעים, על קצב פאנקי ומקפץ.'),
('By the Time I Get to Arizona', 'שיר מחאה נגד אריזונה, שסירבה להכיר ביום הזיכרון למרטין לותר קינג.'),
('Bring tha Noize', 'גרסה חדשה עם להקת המטאל אנת׳ראקס, חיבור מפורסם של ראפ ומטאל.'),
])

add(696, [
'''א טרייב קולד קווסט כבר הופיעו כאן עם People's Instinctive Travels (אלבום 681). The Low End Theory, שיצא ב־1991, הוא אלבומם השני, ורבים רואים בו את אחד מאלבומי ההיפ הופ הגדולים בכל הזמנים. השם, "תיאוריית הצלילים הנמוכים", רומז לבס: קיו־טיפ ועלי שהיד מוחמד בנו את האלבום סביב קווי בס עמוקים של ג׳אז, ואפילו הזמינו את רון קרטר, הבסיסט של מיילס דייוויס, לנגן באחד השירים.''',
'''הצליל מינימלי וחם: בס עמוק, תופים חדים ויבשים, דגימות קצרות של ג׳אז ופאנק, ושני ראפרים שמשלימים זה את זה: קיו־טיפ, רגוע, גבוה וחכם, ופייף דוג, מהיר, מצחיק וקולני, שהפך כאן לשותף שווה. Excursions, הפותח, נפתח בקו בס של ג׳אז, וקיו־טיפ מספר בו איך אביו אמר שהיפ הופ מזכיר לו את הבי־בופ של צעירותו. Check the Rhime הוא שיח קליל בין שני החברים על הימים הראשונים שלהם. Buggin' Out מציג את פייף במלוא כוחו. Scenario, הסוגר, הוא מסיבה פרועה עם להקה צעירה בשם לידרס אוף דה ניו סקול, ובה בוסטה ריימס הצעיר מתפרץ בבית הבלתי נשכח שלו.''',
'''The Low End Theory חיבר בצורה מושלמת בין ג׳אז להיפ הופ, והשפיע על אינספור ראפרים ומפיקים, וגם על נגני ג׳אז. הוא נכלל ברשימות של האלבומים הטובים בכל הזמנים, לא רק בהיפ הופ.''',
'''שמעו את Excursions עם אוזניות, ושימו לב לבס. ואחר כך את Scenario בקול רם, כדי לשמוע את המסיבה. ואם אהבתם, חזרו ל־Kind of Blue של מיילס דייוויס (אלבום 21), אחד המקורות של הצליל הזה.''',
], [
('Excursions', 'הפותח, קו בס של ג׳אז וסיפור על אב שמשווה היפ הופ לבי־בופ.'),
('Check the Rhime', 'שיח קליל וכיפי בין קיו־טיפ לפייף דוג על הימים הראשונים שלהם.'),
('Scenario', 'הסוגר, מסיבה פרועה עם בוסטה ריימס הצעיר בבית בלתי נשכח.'),
])

add(697, [
'''פרל ג׳אם קמו בסיאטל ב־1990, מתוך טרגדיה: הגיטריסט סטון גוסארד והבסיסט ג׳ף אמנט, שניגנו קודם בגרין ריבר עם חברי מאדהאני (אלבום 616), איבדו את הזמר של להקתם הבאה, שמת ממנת יתר. הם הקליטו קטעים בלי שירה, והקלטת הגיעה לאדי ודר, עובד בתחנת דלק בסן דייגו, שכתב עליהם מילים והקליט את קולו. כשהגיע לסיאטל, תוך ימים ספורים הייתה להקה. Ten, אלבום הבכורה, יצא ב־1991.''',
'''הצליל הוא רוק קלאסי, עשיר ורחב, ברוח לד זפלין וניל יאנג: גיטרות גדולות, סולואים של מייק מקרידי, ובעיקר הקול של ודר, עמוק, רועד ורגשי, שנשמע כאילו הוא חי כל מילה. השירים מספרים סיפורים קשים על אנשים שבורים. Alive מתאר צעיר שמגלה שהאיש שגידל אותו אינו אביו האמיתי, ועם השנים הפך להמנון של הישרדות. Even Flow מתאר אדם חסר בית. Jeremy מבוסס על סיפור אמיתי וקשה על נער שנפגע בבית הספר, והקליפ שלו זכה בפרסים רבים. Black הוא שיר פרידה כואב על אהבה שאבדה, אחד היפים של הלהקה.''',
'''בהתחלה האלבום התקדם לאט, אבל אחרי ההצלחה של נירוונה (אלבום 685) הוא התפוצץ, ומכר יותר מעשרה מיליון עותקים באמריקה בלבד. פרל ג׳אם הפכו לאחת הלהקות הגדולות בעולם, וממשיכים להופיע עד היום, בהרכב כמעט זהה. השם Ten לקוח ממספר החולצה של שחקן כדורסל שהלהקה אהבה.''',
'''שמעו את Alive ואחריו את Black: שני הצדדים של אדי ודר, הסוער והשבור. ואחר כך השוו ל־Nevermind של נירוונה (אלבום 685), שיצא באותו חודש. שימו לב גם לגיטרה של מייק מקרידי בסוף Alive: אחד הסולואים המפורסמים של העשור.''',
], [
('Alive', 'סיפור על צעיר שמגלה סוד משפחתי, שהפך להמנון של הישרדות, עם סולו גדול.'),
('Black', 'שיר פרידה כואב על אהבה שאבדה, אחד היפים והמרגשים של הלהקה.'),
('Even Flow', 'שיר על אדם חסר בית, עם ריף סוער ושירה רגשית של אדי ודר.'),
])

add(698, [
'''סיינט אטיין קמו בלונדון בסוף שנות השמונים, כשני חברי ילדות, בוב סטנלי ופיט וויגס, שהיו בעיקר מעריצים ואספני תקליטים: סטנלי כתב על מוזיקה בעיתונות, והם אהבו פופ בריטי של שנות השישים, סול, פסקולים של סרטים ומוזיקת האוס חדשה. את השם הם לקחו מקבוצת כדורגל צרפתית. אחרי כמה זמרות אורחות, הצטרפה אליהם הזמרת שרה קרקנל, והפכה לפנים ולקול של הלהקה. Foxbase Alpha, אלבום הבכורה, יצא ב־1991.''',
'''הצליל הוא חיבור מתוק ונוסטלגי בין פופ של שנות השישים לבין מוזיקת מועדונים: קצבים של האוס ודאב, דגימות מסרטים, מתקליטים ישנים ומרחובות לונדון, ומעל הכל הקול הרך, השקט והאנגלי של קרקנל. האלבום נשמע כמו טיול אחר הצהריים בלונדון, עם רדיו ישן ביד. Only Love Can Break Your Heart, הסינגל הראשון, הוא גרסת ריקוד חלומית לשיר של ניל יאנג מ־After the Gold Rush (אלבום 185). Nothing Can Stop Us הוא שיר פופ שמח ונלהב, עם דגימה של דאסטי ספרינגפילד. Spring קליל ורענן, ו־Kiss and Make Up שקט ומתוק. בין השירים יש קטעים קצרים של קולות, שיחות וצלילים של העיר. Carnt Sleep ו־London Belongs to Me נשמעים כמו גלויות קטנות מלונדון של תחילת שנות התשעים.''',
'''סיינט אטיין לא הפכו לכוכבים גדולים, אבל זכו לקהל נאמן מאוד, והשפיעו על הרבה להקות פופ ואינדי שחיברו בין עבר להווה, בין גיטרות לאלקטרוניקה. הם ממשיכים להקליט עד היום, ונחשבים לאחת הלהקות האוהבות והחכמות של הפופ הבריטי.''',
'''שמעו את Only Love Can Break Your Heart, ואחריו את המקור של ניל יאנג מ־After the Gold Rush (אלבום 185): אותו שיר עצוב, פעם עם גיטרה ופעם עם קצב של מועדון.''',
], [
('Only Love Can Break Your Heart', 'גרסת ריקוד חלומית לשיר של ניל יאנג, עם קצב רך ושירה שקטה.'),
('Nothing Can Stop Us', 'שיר פופ שמח ונלהב, עם דגימה של דאסטי ספרינגפילד וקצב קופצני.'),
('Spring', 'שיר קליל ורענן כמו בוקר אביבי בלונדון, עם קול רך ומתוק.'),
])

add(699, [
'''ספולטורה באו מבלו הוריזונטה שבברזיל, ובמרכזם שני אחים, מקס ואיגור קבלרה, שהקימו את הלהקה כשהיו עדיין בני נוער, בתחילת שנות השמונים. הם התחילו כלהקת מטאל קיצונית וגסה, מושפעת מסלייר (אלבום 575) ומלהקות אירופיות, ובמהלך השנים הפכו ללהקת המטאל הגדולה ביותר שיצאה מאמריקה הלטינית. Arise, שיצא ב־1991, הוקלט בפלורידה עם המפיק סקוט ברנס, והוא האלבום שהפך אותם לכוכבים בעולם.''',
'''הצליל כבד, מהיר ועוצמתי: ריפים חזקים של מקס קבלרה והגיטריסט אנדראס קיסר, בס עמוק, ותופים מדויקים ומהירים של איגור, שנחשב לאחד המתופפים הטובים במטאל. מקס צועק בקול עמוק וזועם על מלחמה, על אלימות, על עוני ועל המצב בעולם. Arise, שיר הנושא, פותח בסערה של תופים וגיטרות. Dead Embryonic Cells מהיר וחד, ואחד השירים המוכרים שלהם. Desperate Cry מתחיל בגיטרה אקוסטית שקטה, ואז מתפוצץ. Altered State נפתח בתופים שבטיים, רמז לכיוון שהלהקה תלך אליו בהמשך, כשתחבר מטאל עם מקצבים ברזילאיים ואינדיאניים.''',
'''Arise מכר מאות אלפי עותקים, וספולטורה הופיעו מול קהל ענק בברזיל ובעולם. כמה שנים אחר כך הם הוציאו את Roots, שבו שילבו מטאל עם מוזיקה של שבטים בברזיל, והשפיעו על כל המטאל של שנות התשעים. מקס עזב את הלהקה ב־1996, אבל ספולטורה המשיכו לנגן עשרות שנים.''',
'''שמעו את Desperate Cry, ושימו לב לרגע שבו הפתיחה השקטה הופכת לסערה. ואחר כך השוו ל־Reign in Blood של סלייר (אלבום 575), אחת ההשפעות הגדולות עליהם.''',
], [
('Arise', 'שיר הנושא, סערה של תופים וגיטרות מהירות, ושירה עמוקה וזועמת.'),
('Dead Embryonic Cells', 'שיר מהיר וחד, אחד המוכרים שלהם, עם ריף שלא נותן לנשום.'),
('Desperate Cry', 'מתחיל בגיטרה אקוסטית שקטה, ואז מתפוצץ לסערה כבדה ומרגשת.'),
])

add(700, [
'''סלינט באו מלואיוויל שבקנטקי, ארבעה צעירים שגדלו בסצנת הפאנק המקומית: בריאן מקמהאן, דייוויד פאחו, בריט וולפורד וטוד בראשיר. Spiderland, שיצא ב־1991, הוא אלבומם השני, והוקלט בכמה ימים בלבד. עוד לפני שהאלבום יצא, הלהקה התפרקה, ולכן כמעט לא הופיעה איתו. על העטיפה מופיע צילום בשחור לבן של ארבעת החברים, ראשיהם בלבד מעל המים, במחצבה מוצפת, צילום של חברם וויל אולדהם.''',
'''המוזיקה שקטה ורועשת לסירוגין, ובנויה כמו סיפורים קצרים: גיטרות נקיות שמנגנות מנגינות חוזרות ומהפנטות, בס ותופים שמשנים קצב באופן מפתיע, ושקט ארוך שמתפוצץ פתאום לרעש עצום. מקמהאן כמעט לא שר: הוא לוחש, מדבר ומספר סיפורים מוזרים ומפחידים. Breadcrumb Trail מספר על ביקור ביריד ועל פגישה עם מגדת עתידות. Nosferatu Man כבד ואפל, Washer הוא שיר ארוך, עצוב ואיטי מאוד, ו־Good Morning, Captain, הסוגר, מספר סיפור של ספינה טרופה, ומסתיים בצעקה כואבת אחרי דקות של מתח.''',
'''בזמנו כמעט אף אחד לא שמע את Spiderland, אבל השמועות עליו התפשטו, והוא נחשב היום לאבן היסוד של הסגנון שנקרא "פוסט־רוק", שבו להקות כמו מוגוואי ו־גודספיד יו! בלאק אמפרור בנו שירים ארוכים, שקטים ורועשים, בלי פזמונים רגילים. מעטים האלבומים שהשפיעו כל כך תוך כדי שנמכרו כל כך מעט.''',
'''שמעו את Spiderland לבד, בחושך, ברצף ובקול רם יחסית, כדי שתשמעו גם את הלחישות. ואם אהבתם, נסו את Spirit of Eden של טוק טוק, שבא מכיוון אחר לגמרי אל אותו שקט. זה לא אלבום קל, אבל מי שנכנס לעולם שלו, לא שוכח אותו.''',
], [
('Breadcrumb Trail', 'סיפור לוחש על ביקור ביריד ופגישה עם מגדת עתידות, שקט שמתפוצץ לרעש.'),
('Good Morning, Captain', 'הסוגר, סיפור של ספינה טרופה, שמסתיים בצעקה כואבת אחרי דקות של מתח.'),
('Washer', 'שיר ארוך, עצוב ואיטי מאוד, עם גיטרות נקיות ושקט שמתנפץ.'),
])
